(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c19"]=[{"id":"00005381","register_sub_id":"101","register_pk":"106369","name":"綾菊酒造西酒蔵","kana":"あやきくしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"香川県","address":"香川県綾歌郡綾川町山田下字桜本3393-1","lat":34.22300466,"lng":133.94724214,"geo_status":"db","era":"昭和25","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、瓦葺、建築面積474㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0307","desc":"仲酒蔵に並列して南北棟で建つ。桁行１６ｍ，梁間１３ｍ規模，切妻造，桟瓦葺の２階建酒蔵の南方に，棟を高くした桁行１９ｍ，梁間１４ｍ，切妻造，赤色桟瓦葺の酒蔵を繋げる。国道に面する西面南方部は２段の窓を設けた縦板張の外装をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005381"},{"id":"00000273","register_sub_id":"101","register_pk":"101263","name":"大川酒店","kana":"おおかわさけてん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市上吉田町三丁目１０５２－１、１０５３、１０５４","lat":34.2287467,"lng":133.78201641,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建，瓦葺，建築面積182㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"37 － 0008","desc":"道に面して建つ２階建て平入の酒造業を営んだ家の店舗兼主屋。２階部を黒漆喰塗りとして，正面に大正12年から製造している酒の銘柄を描く。２階の立ちが高く，屋根にむくりを付けた重厚な外観から，旧家を思わせる佇まいの酒店として広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000273"},{"id":"00004039","register_sub_id":"101","register_pk":"105029","name":"大森醤油醸造所麹庫","kana":"おおもりしょうゆじょうぞうしょこうじこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3272-1","lat":34.5449189,"lng":134.28342796,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺及びスレート葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0204","desc":"醸造所敷地西南隅に位置し，石垣基礎の上に南北棟で建つ。桁行４間半梁間３間，切妻造，桟瓦葺，内部２室の麹室で，外周は２重壁に造り，室の天井は竹簀の子とする。外観は腰を縦板張，上部を白漆喰塗壁とし，天井懐にあたる高い位置に温度調整の窓を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004039"},{"id":"00004041","register_sub_id":"101","register_pk":"105031","name":"大森醤油醸造所仕込蔵","kana":"おおもりしょうゆじょうぞうしょしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3272-1","lat":34.544979,"lng":134.28367528,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、スレート葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0206","desc":"槽場の東方に南北棟，２棟並びで建つ。ともに桁行は５間半，梁間は西庫が４間，東庫が３間で，切妻造，スレート葺（もと瓦葺）とする。内部は中央に柱を建てて二重梁式とし，外観は腰縦板張で上部に横連子窓を配する。醸造所の核となる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004041"},{"id":"00004040","register_sub_id":"101","register_pk":"105030","name":"大森醤油醸造所槽場及び操作場","kana":"おおもりしょうゆじょうぞうしょふなばおよびそうさば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3272-1","lat":34.54493066,"lng":134.28352234,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0205","desc":"麹庫の東方に位置し，東西棟で建つ。桁行５間梁間３間規模，切妻造，桟瓦葺で，北面に桁行５間梁間１間半のもと釜場を添わす。内部小屋組は登り梁式で，外観は腰縦板張とし，上部に「いわく窓」と呼ばれる横連子窓を配し，北面は湾曲した庇持送りを用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004040"},{"id":"00003612","register_sub_id":"101","register_pk":"104602","name":"かめびし赤門","kana":"かめびしあかもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22872507,"lng":134.40353069,"geo_status":"db","era":"江戸末期／昭和初期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、間口1.8m、土塀付属","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0169","desc":"敷地北辺のほぼ中央，十三号蔵の西妻面に接して建つ。間口４．５ｍ奥行５．７ｍ規模，入母屋造，本瓦葺の門で，西北端に北塀が取り付く。東面は十三号蔵により切られた形になっており，もとは天保１４年（１８４３）築の長屋門を改造したものとみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003612"},{"id":"00003603","register_sub_id":"101","register_pk":"104593","name":"かめびし一号蔵","kana":"かめびしいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22833055,"lng":134.40319972,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0160","desc":"敷地の西南角に位置し，主屋の南方に南北棟で建つ。桁行１２ｍ梁間５ｍ規模，切妻造，本瓦葺の平屋建土蔵。もとは醤油原料の大豆貯蔵庫で，北西端に接して通用門を開く。腰は海鼠壁仕上げで，主屋，蔵と同様にべんがら色に塗り廻して独特の街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003603"},{"id":"00003614","register_sub_id":"101","register_pk":"104604","name":"かめびし五号蔵","kana":"かめびしごごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22876462,"lng":134.40309748,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0171","desc":"西敷地の東北隅に位置し，圧搾場の北に接して東西棟で建つ。桁行１３．６ｍ梁間６ｍ規模，切妻造，本瓦葺の諸味蔵で，通りに面する東妻面と北面はモルタル壁をべんがら色に塗り，かめびし特有のべんがら色通り景観の演出に一役買っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003614"},{"id":"00003611","register_sub_id":"101","register_pk":"104601","name":"かめびし作業場","kana":"かめびしさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22857387,"lng":134.40348562,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造3階建、瓦葺、建築面積105㎡","structure_material":"木造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0168","desc":"主屋（事務室・展示室）の東方，離れ座敷（資材置場）の北方に建つ。桁行１５ｍ梁間７ｍ規模，切妻造，桟瓦葺の木造２階建で，東端を３階建とする。もとは２階は醤油殺菌加熱場として使用され，３階部は空気抜きの役割をもったとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003611"},{"id":"00003605","register_sub_id":"101","register_pk":"104595","name":"かめびし三号蔵","kana":"かめびしさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22827517,"lng":134.40367576,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0162","desc":"仕込み部屋の東方，敷地の東南隅に位置し，敷地東辺に沿って南北棟で建つ。桁行１１ｍ梁間７．７ｍ規模，切妻蔵，本瓦葺の平屋建で，諸味貯蔵庫として使われているが，屋根に越屋根をあげていることから，もとは釜場であったとみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003605"},{"id":"00003604","register_sub_id":"101","register_pk":"104594","name":"かめびし仕込み部屋","kana":"かめびししこみべや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22831631,"lng":134.40338272,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0161","desc":"一号蔵の東方に位置し，敷地南辺に沿って東西棟で建つ。桁行２４ｍ梁間７．５ｍ規模，切妻造，桟瓦葺の平屋建土蔵で，内部には二重壁，中二階の麹室５部屋を設ける。温度調節用の小窓など，筵を用いた麹づくりのための造作が随所にみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003604"},{"id":"00003607","register_sub_id":"101","register_pk":"104597","name":"かめびし十一号蔵","kana":"かめびしじゅういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22858605,"lng":134.40368427,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0164","desc":"十号蔵の北方に位置し，敷地東辺に沿って南北棟で建つ。桁行９．８ｍ梁間５．２ｍ規模，切妻造，本瓦葺の平屋建で，岡田家の記録にある文化４年（１８０７）５月上棟の「二の倉」に比定されている。かめびし創業期の歴史を伝える醤油蔵のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003607"},{"id":"00003606","register_sub_id":"101","register_pk":"104596","name":"かめびし十号蔵","kana":"かめびしじゅうごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22854377,"lng":134.403687,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0163","desc":"三号蔵の北方，もと離れ座敷（資材置場）の東方に位置し，敷地東辺のほぼ中央に東西棟で建つ。桁行１１．５ｍ梁間６．２ｍ規模，切妻造，本瓦葺の平屋建で，諸味貯蔵庫として使われているが，内部は天井が高く，もとは醤油醸造蔵とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003606"},{"id":"00003609","register_sub_id":"101","register_pk":"104599","name":"かめびし十三号蔵","kana":"かめびしじゅうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22869814,"lng":134.40365283,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0166","desc":"十二号蔵の北西方に位置し，敷地北辺の東寄りに東西棟で建つ。桁行１０ｍ梁間５ｍ規模，切妻造，本瓦葺の平屋建で，屋根に越屋根を載せる。腰を海鼠壁，上部をべんがら色に塗り，主屋前の通りから北へ廻り込む通り景観の端部を納める役割を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003609"},{"id":"00003608","register_sub_id":"101","register_pk":"104598","name":"かめびし十二号蔵","kana":"かめびしじゅうにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.2286384,"lng":134.40368665,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0165","desc":"敷地東辺の北寄りに位置し，十一号蔵の北妻面に接して南北棟で建つ。桁行７．４ｍ梁間６ｍ規模で，東側屋根面が長い招き造としている点に特徴がある。外装はもと焼杉の縦板張で，東桁行面に水切瓦を付けて変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003608"},{"id":"00003610","register_sub_id":"101","register_pk":"104600","name":"かめびし十四号蔵","kana":"かめびしじゅうよんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県東かがわ市引田2174","lat":34.22843042,"lng":134.40368772,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0167","desc":"三号蔵と十号蔵の間に位置し，敷地東辺に沿って南北棟で建つ。桁行９．８ｍ梁間５．２ｍ規模，切妻造，本瓦葺の平屋建で，岡田家の記録にある享和２年（１８０１）４月上棟の「五間倉」に比定されている。かめびし創業期の歴史を伝える醤油蔵のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003610"},{"id":"00003616","register_sub_id":"101","register_pk":"104606","name":"かめびし七号蔵","kana":"かめびしななごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.2288019,"lng":134.402786,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0173","desc":"西敷地の北西隅に位置し，西敷地北辺に沿って東西棟で建つ。桁行１６ｍ梁間１０．２ｍ規模，切妻造，鉄板葺の平屋建で，通り沿いの北面上部には５つの窓を開ける。年代ものの諸味貯蔵庫として使用され，内部には１６個の丸桶と３個の角桶を収容する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003616"},{"id":"00003617","register_sub_id":"101","register_pk":"104607","name":"かめびし八号蔵","kana":"かめびしはちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県東かがわ市引田2132","lat":34.22867117,"lng":134.40272572,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0174","desc":"西敷地の西辺沿いに位置する。花崗石基礎に建つ南北棟，切妻造，本瓦葺，桁行２０．８ｍ梁間６．８ｍの比較的長大な諸味蔵で，内部には２０個のコンクリート製内側板張の角桶を据える。七号蔵とともに西敷地における醤油醸造施設の中核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003617"},{"id":"00002999","register_sub_id":"101","register_pk":"103989","name":"川鶴酒造鶴鳴舘（旧瓶詰蔵）","kana":"かわつるしゅぞうかくめいかん（きゅうびんづめぐら）","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町1032-1","lat":34.126812,"lng":133.708649,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0124","desc":"明治蔵の西南方に位置し，東西棟で建つ。桁行１４ｍ，梁間１０ｍ規模，切妻造，桟瓦葺の平屋建で，北面中央に大戸口を，南面には３尺角の小窓を４箇所開ける。南側敷地南辺における醸造所景観の主要素になる。現在はコンサート会場等として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002999"},{"id":"00002995","register_sub_id":"101","register_pk":"103985","name":"川鶴酒造麹蔵","kana":"かわつるしゅぞうこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町836","lat":34.1276995,"lng":133.70827767,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、スレート葺、建築面積180㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0120","desc":"西酒蔵の東方に同じ軒高９ｍ，南北棟で並び建つ。桁行２０ｍ，梁間９ｍ規模，切妻造２階建で，２階に麹室を造り，現在も麹室として利用されている。北妻面は西酒蔵と一体となり，醸造場北面の景観を構成する上で欠くことのできない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002995"},{"id":"00002994","register_sub_id":"101","register_pk":"103984","name":"川鶴酒造西酒蔵","kana":"かわつるしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町836","lat":34.127789,"lng":133.708221,"geo_status":"db","era":"大正7／昭和10頃増築","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積400㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0119","desc":"財田川に並行する阿波街道の北側敷地に南北棟で建つ。北方は仕込蔵で桁行１３間と規模が大きく，地棟墨書から年代が知られ，糟場となる南方は室戸台風後の再建になる。規則的に小窓を配した長大な西桁行面は観音寺市街方面からの格好のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002994"},{"id":"00002996","register_sub_id":"101","register_pk":"103986","name":"川鶴酒造濾過蔵","kana":"かわつるしゅぞうろかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県観音寺市本大町836","lat":34.12757875,"lng":133.70805912,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、スレート葺、建築面積308㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0121","desc":"麹蔵の東方に位置し，麹室とは棟を直交させた東西棟で建つ。桁行２２ｍ，梁間１４ｍ規模，切妻造２階建で，麹蔵と軒高を揃える。北面は腰を杉板張，上部を漆喰壁とし，小庇付きと鉄戸付きの小窓を２段に配置する。醸造所北面を構成する主要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002996"},{"id":"00004655","register_sub_id":"101","register_pk":"105645","name":"キッコ石石井家住宅醤油蔵","kana":"きっこいしいしいけじゅうたくしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲262","lat":34.47624914,"lng":134.32176921,"geo_status":"db","era":"明治18頃","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積219㎡、井戸及び洗い場付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0247","desc":"住宅屋敷地の南方，石垣擁壁下に位置する。桁行１４ｍ梁間１０ｍ規模，南北棟，切妻造，桟瓦葺の諸味蔵の東に，梁間６ｍで東面に下屋庇を差し掛けた醤油蔵を並べる。東面下屋中央部には石造井戸と洗い場が付属する。醤油醸造場の中心となる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004655"},{"id":"00004654","register_sub_id":"101","register_pk":"105644","name":"キッコ石石井家住宅納屋","kana":"きっこいしいしいけじゅうたくなや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字坂ノ山甲255","lat":34.47629993,"lng":134.321671,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0246","desc":"土蔵下から南へ下る小路に東妻面を見せて建つ。石積基礎に建つ東西棟，切妻造，桟瓦葺，妻入の木造平屋建で，平面規模は桁行２間半梁間２間。外壁は土壁を表した素朴な建物であるが，屋敷地南方の醤油醸造場敷地の一画を構成する要素になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004654"},{"id":"00010358","register_sub_id":"101","register_pk":"199130","name":"旧鎌田醤油大門","kana":"きゅうかまだしょうゆおおもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県坂出市本町1-3542-2","lat":34.314901,"lng":133.853626,"geo_status":"db","era":"明治前期／昭和30年頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0398","desc":"敷地東に門を開く。桁行三間梁間三間、切妻造本瓦葺で、棟通りよりやや前寄りに五平の柱を立てて門口とする。両開きの大扉及び両脇の片開潜戸は八双や乳金物、四葉金物で豪壮に飾る。長屋門風の構えだが、両側面を開放とし、小屋組を表すなど特異な形式の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010358"},{"id":"00010357","register_sub_id":"101","register_pk":"199129","name":"旧鎌田醤油本店","kana":"きゅうかまだしょうゆほんみせ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県坂出市本町1-3541-7他","lat":34.315046,"lng":133.853433,"geo_status":"db","era":"江戸末期／平成16年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積211㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0397","desc":"商店街の通りに北面する醤油商本店。建ちの高い二階建で入母屋造本瓦葺とし、背面に切妻造の屋根を突出す。表側外壁は大壁黒漆喰塗で格子窓を並べる。一階は中央が幅二間の通り土間で西をミセとし、二階には接客用の座敷を設ける。近世商家の佇まいを残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010357"},{"id":"00002835","register_sub_id":"101","register_pk":"103825","name":"京宝亭佃煮販売処店舗（旧黒島伝九郎醤油醸造場醤油蔵）","kana":"きょうほうていつくだにはんばいどころてんぽ（きゅうくろしまでんくろうしょうゆじょうぞうじょうしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2126","lat":34.46468,"lng":134.318512,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造平屋建、杉皮及びスレート葺、建築面積110㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0103","desc":"小豆島内海湾沿いに南北に走る主要地方道坂手港線の浜側に南北棟で東面して建つ。もと「伝九郎」醤油醸造場の醤油蔵で，昭和２３年から佃煮製造所となり，現在は桁行１１ｍ，梁間１０ｍ規模に切縮められて佃煮販売所の店舗として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002835"},{"id":"00002836","register_sub_id":"101","register_pk":"103826","name":"京宝亭佃煮販売処西棟（旧黒島伝九郎醤油醸造場醤油蔵）","kana":"きょうほうていつくだにはんばいどころにしとう（きゅうくろしまでんくろうしょうゆじょうぞうじょうしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2126","lat":34.46471,"lng":134.318375,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積133㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0104","desc":"販売処店舗の西方浜側に東西棟で建つ。桁行１４．８ｍ，梁間９ｍ規模，桟瓦葺，切妻造の平屋建土蔵で，花崗石の基礎に建ち，屋根に煙出しの越屋根を載せる。店舗棟とともに佃煮製造草創期ゆかりの建造物で，小豆島「醤の里」の景観形成要素のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002836"},{"id":"00004436","register_sub_id":"101","register_pk":"105426","name":"金大醤油醤油蔵","kana":"きんだいしょうゆしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲833","lat":34.47645204,"lng":134.319244,"geo_status":"db","era":"昭和2／昭和9増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺一部スレート葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0227","desc":"高さの異なる切妻造，平屋建を２棟並べた形式で，主屋西側に近接して建つ。低い部分が当初で，鋸屋根風の部分は増築。諸味蔵との取合いは下屋で処理している。複雑な外観であるが，桟瓦葺，縦板壁で統一されており，醸造施設らしい景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004436"},{"id":"00004437","register_sub_id":"101","register_pk":"105427","name":"金大醤油諸味蔵","kana":"きんだいしょうゆもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲833","lat":34.47646859,"lng":134.31906504,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積99㎡","structure_material":"土蔵造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0228","desc":"敷地西側にあり，細長い切妻造，平屋建を２棟並べた形式である。北側は桁行２２ｍ，南側は増築部でひとまわり小さい。街路に面した北側は，壁面上半に大振りな開口部を規則的に並べる。桟瓦葺，縦板壁で統一されており，醸造施設の景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004437"},{"id":"00003139","register_sub_id":"101","register_pk":"104129","name":"金両北諸味蔵","kana":"きんりょうきたもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47697266,"lng":134.318039,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積777㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0132","desc":"内海湾馬木港の東方，馬木川左岸南方の台形状敷地の北西隅に東西棟で建つ。桁行８０ｍ規模，切妻造，桟瓦葺の醤油蔵で，高い腰を板張り，上部の窓部を漆喰塗とした長大な北面を馬木川沿いの道路に見せる。敷地北半を占める醤油醸造部の中心的建造物になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003139"},{"id":"00003140","register_sub_id":"101","register_pk":"104130","name":"金両醤油蔵","kana":"きんりょうしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.476852,"lng":134.318268,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0133","desc":"北諸味蔵の東半の南方に並び建つ。桁行２２ｍ規模，東西棟，切妻造，桟瓦葺の平屋建で，棟のほぼ全長に亘って越屋根をあげている点に特徴がある。小屋はキングポストトラスとする。もと麹原料混合場及び機械場で，西半を醤油販売処として活用している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003140"},{"id":"00004027","register_sub_id":"101","register_pk":"105017","name":"香龍北川家住宅酒蔵","kana":"こうりゅうきたがわけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市円座町字永井979-1","lat":34.28922084,"lng":134.01388654,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積491㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0192","desc":"主屋の背後に位置し，東西棟で建つ。桁行２０間梁間６間規模，切妻造，桟瓦葺，平入の仕込蔵の南面西寄に，桁行７間梁間３間，東西棟，切妻造，桟瓦葺の麹室を添わす。酒造場の核となる施設で，仕込蔵の２階の一部には酒母造場を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004027"},{"id":"00002840","register_sub_id":"101","register_pk":"103830","name":"左海醤油工業醤油蔵","kana":"さかいしょうゆこうぎょうしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.46464564,"lng":134.31897426,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積277㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0108","desc":"左海醤油丘工場の中核的施設になり，主要地方道の東側，道路に沿って南北棟で建つ。桁行１７ｍ，梁間１１ｍ規模，桟瓦葺，切妻造の南に桁行９ｍ，梁行１０ｍ規模の切妻造を繋げる。道路を隔てたもと浜工場の醤油蔵と向き合い醤油醸造盛期の活況を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002840"},{"id":"00002841","register_sub_id":"101","register_pk":"103831","name":"左海醤油工業水圧式蓄量機小屋","kana":"さかいしょうゆこうぎょうすいあつしきちくりょうきごや","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.46503313,"lng":134.31870758,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、杉皮葺、建築面積5.8㎡、水圧式畜量機付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0109","desc":"醤油蔵の北方，主要地方道沿いに南北棟で建つ。桁行及び梁間２．４ｍ規模の切妻造の小屋で，コンクリート製５段の井籠組を外周柱のガイドレールに沿って上下させる蓄量機を内部に装置する。諸味圧搾機の動力装置で，醤油醸造の近代化を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002841"},{"id":"00001735","register_sub_id":"101","register_pk":"102725","name":"四国村土佐の楮蒸し小屋","kana":"しこくむらとさのこうぞむしごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県高松市屋島中町126-2","lat":34.345791,"lng":134.10993779,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、茅葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"37 － 0035","desc":"もと高知県高岡郡檮原町越智面に所在した。土佐紙の原料である楮や三椏を蒸すための小屋。内部に石で窯を築き、蓋として釜にかぶせる大桶を上げ下げする装置をもつ。寄棟造、茅葺で、外壁をも茅で葺いている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001735"},{"id":"00003147","register_sub_id":"101","register_pk":"104137","name":"島醸諸味蔵","kana":"しまじょうもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町西村字久徳甲250-2","lat":34.47659852,"lng":134.2913867,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積922㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0140","desc":"内海湾の北方，清水海岸沿いに走る国道に面する工場地の西方に建つ。もと丸金醤油清水工場の醤油蔵で，桁行９４ｍ規模の南北棟，切妻造，桟瓦葺とする。内部は諸味桶を４列に並べる。「古式本醸造諸味蔵」の看板を掲げ，他の近代的な醸造施設と対照をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003147"},{"id":"00003137","register_sub_id":"101","register_pk":"104127","name":"正金醤油西諸味蔵","kana":"しょうきんしょうゆにしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町石井甲230-1","lat":34.476292,"lng":134.320389,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0130","desc":"内海湾馬木港東方に位置し，馬木川に直交する道路に南妻面を見せて建つ。もと金両醤油創業時の醤油蔵で，桁行１０間梁間５間規模とし内部に４列３２個の諸味桶を並べる。南北棟，切妻造，桟瓦葺の平屋建で，南面を杉板張りとして小路の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003137"},{"id":"00003138","register_sub_id":"101","register_pk":"104128","name":"正金醤油東諸味蔵","kana":"しょうきんしょうゆひがしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町石井甲230-1","lat":34.47641,"lng":134.320633,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0131","desc":"西諸味蔵の東方，敷地東辺沿い道路に東妻面を見せて建つ。西諸味蔵と同様，もと金両醤油創業時の醤油蔵で，規模はやや小さく内部には４列２４個の諸味桶を容れる。東西棟，切妻造，桟瓦葺の平屋建で，杉板張りの東妻面に敷地形状に合わせた下屋を張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003138"},{"id":"00004671","register_sub_id":"101","register_pk":"105661","name":"正金藤井家住宅物置","kana":"しょうきんふじいけじゅうたくものおき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲813-1","lat":34.47533086,"lng":134.32070828,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0263","desc":"主屋の南方に位置し，敷地東南隅に東西棟で建つ。切妻造，桟瓦葺の木造平屋建で，南北両面に下屋を差し掛け，南下屋の東端を隅切りとする。外部は腰焼杉縦板張，上部白漆喰塗で，境に水切を入れる。白壁部に穿たれた円形小窓が特徴ある外観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004671"},{"id":"00003328","register_sub_id":"101","register_pk":"104318","name":"小豆島馬越醤油煙突","kana":"しょうどしまうまごえしょうゆえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.521538,"lng":134.210892,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ15m","structure_material":"煉瓦造","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0155","desc":"敷地のほぼ中央，製成場の北にある。角形平面で煉瓦造イギリス積の煙突で，頂部は上下二段に蛇腹を廻し，その間に屋号を飾る。高１５ｍの規模を有し，周辺の眺望上，際だった存在となっており，また製成場と連絡した近代醸造施設の景観もつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003328"},{"id":"00003325","register_sub_id":"101","register_pk":"104315","name":"小豆島馬越醤油北諸味蔵","kana":"しょうどしまうまごえしょうゆきたもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.521984,"lng":134.210983,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0152","desc":"海岸寄りに建ち，醤油醸造の創業期の建築と考えられている。東西に長大な木造・平屋建，切妻造・桟瓦葺で西端部を棟違いにする。側廻りは腰まで切石積で，真壁造の外壁を縦板で覆う。内部は棟通りに中柱を立て，水平梁と登梁を組み，整然と木桶を配している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003325"},{"id":"00003324","register_sub_id":"101","register_pk":"104314","name":"小豆島馬越醤油製成場","kana":"しょうどしまうまごえしょうゆせいせいじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.52133257,"lng":134.2108742,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積400㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0151","desc":"醸造会社の設立時に建てられた中心施設。東西に長大な木造・平屋建で，切妻造・桟瓦葺の中央部を高く立ち上げ，南・北・西の各面に下屋を廻す。内部は柱や梁などに瓜剥状の大径材を用いて高大な空間をつくりだしている。近代における大規模な醸造施設の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003324"},{"id":"00003327","register_sub_id":"101","register_pk":"104317","name":"小豆島馬越醤油道具蔵","kana":"しょうどしまうまごえしょうゆどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.521564,"lng":134.210464,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積42㎡","structure_material":"土蔵造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0154","desc":"製成場の北西，海岸寄りに建つ。土蔵造・平屋建で，東西棟の切妻造・本瓦葺で，北側面西端に出入口を設け，庇をつける。漆喰塗の外壁は縦板張で覆う。北諸味蔵と同じく醤油醸造の創業期の建築と考えられており，江戸末期の醸造施設の様相を伝えるものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003327"},{"id":"00003326","register_sub_id":"101","register_pk":"104316","name":"小豆島馬越醤油南諸味蔵","kana":"しょうどしまうまごえしょうゆみなみもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町馬越字前浜甲161","lat":34.52189041,"lng":134.21099686,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積300㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"37 － 0153","desc":"北諸味蔵の南に並んで建ち，記録から明治３４年上棟と判明する。東西に長大な木造・平屋建，切妻造・桟瓦葺で，北諸味蔵より桁行規模は少し短い。側廻りは真壁造の外壁を縦板で覆う。架構は棟通りの中柱や各梁などに大径材を用い，伝統的手法を踏襲している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003326"},{"id":"00004641","register_sub_id":"101","register_pk":"105631","name":"小豆島食品（旧岡醤油醸造所）事務所","kana":"しょうどしましょくひん（きゅうおかしょうゆじょうぞうしょ）じむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町草壁本町字下川西493-1","lat":34.4810489,"lng":134.30409366,"geo_status":"db","era":"明治中期／昭和2増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺及びスレート葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0233","desc":"醤油佃煮蔵の東方，別当川沿いに南北棟で建つ。桁行２間半梁間２間規模，片入母屋造，桟瓦葺の木造平屋建で，西面に下屋を差し掛け，北面には切妻造，スレート葺の木造平屋建を増築。もと蔵人部屋で，現在は事務所として使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004641"},{"id":"00004640","register_sub_id":"101","register_pk":"105630","name":"小豆島食品（旧岡醤油醸造所）醤油佃煮蔵","kana":"しょうどしましょくひん（きゅうおかしょうゆじょうぞうしょ）しょうゆつくだにぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町草壁本町字下川西493-1","lat":34.481075,"lng":134.303909,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積401㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0232","desc":"内海湾に注ぐ別当川右岸に接する敷地の西方に東西棟，２棟並びで建つ。北棟は桁行２５ｍ梁間９ｍ規模，南棟は桁行２０ｍ梁間８ｍ規模，ともに切妻造，桟瓦葺で，北棟には棟中央に煙出しの越屋根を上げる。醤油醸造所の中心的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004640"},{"id":"00004430","register_sub_id":"101","register_pk":"105420","name":"高橋商店北醤油蔵","kana":"たかはししょうてんきたしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47926275,"lng":134.31538656,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0221","desc":"桁行２２ｍの大規模な醸造蔵で，主屋の後方にある。木造平屋建，外壁は漆喰塗を縦板で覆い，整然と小窓を並べる。屋根は切妻造，桟瓦葺で，越屋根を設け，西端は棟を下げる。登梁を併用した和小屋により，高大な内部空間をつくる。伝統的な形式の醸造施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004430"},{"id":"00004431","register_sub_id":"101","register_pk":"105421","name":"高橋商店隅土蔵","kana":"たかはししょうてんすみどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47916256,"lng":134.31521154,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、スレート葺、建築面積49㎡、脇門付","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0222","desc":"敷地北西隅にあり，現在は物置としている。乱石積の基礎に建つ土蔵造２階建で，太い側柱を立て強固に固める。屋根は切妻造，波形スレート葺で，外壁は縦板で覆い，軒鉢巻の漆喰は現す。離れ屋との間には，切妻造の脇門を設ける。屋敷後方の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004431"},{"id":"00004429","register_sub_id":"101","register_pk":"105419","name":"高橋商店長屋門（旧製麹室）","kana":"たかはししょうてんながやもん（きゅうせいきくしつ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47895863,"lng":134.31553375,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0220","desc":"主屋の南方にある。木造平屋建，切妻造，桟瓦葺で，東端は棟を下げ，中央東寄りに門口を開き，西側はもと麹室としていた。外壁は漆喰塗，腰を縦板で覆い，門口廻りに換気用の丸窓を設ける。桁行２６ｍの長大な長屋門で，豪壮な屋敷正面の構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004429"},{"id":"00004433","register_sub_id":"101","register_pk":"105423","name":"高橋商店東醤油蔵","kana":"たかはししょうてんひがししょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47923739,"lng":134.31582678,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0224","desc":"主屋東方，南醤油蔵の北に並ぶ。桁行１２ｍ規模の木造平屋建，切妻造，本瓦葺，平入で，外壁は漆喰塗，街路側を縦板で覆い，軒に鉢巻をつける。内部は桁行中央に間仕切を設け，曲梁を用いた和小屋と登梁を併用して高い空間をつくる。醸造業に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004433"},{"id":"00004432","register_sub_id":"101","register_pk":"105422","name":"高橋商店南醤油蔵","kana":"たかはししょうてんみなみしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字植松甲142","lat":34.47911539,"lng":134.31586112,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0223","desc":"主屋東方にあり，もと樽の製作場としていた。桁行１８ｍ，木造平屋建，外壁は漆喰塗，腰を縦板で覆い，整然と小窓を並べる。屋根は切妻造，桟瓦葺で，中央を和小屋，両端を登梁式とし，高い内部空間をつくる。伝統的な形式で，醸造施設の構成の一端を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004432"},{"id":"00002838","register_sub_id":"101","register_pk":"103828","name":"宝食品北佃煮原料蔵（旧左海醤油醸造所醤油蔵）","kana":"たからしょくひんきたつくだにげんりょうぐら（きゅうさかいしょうゆじょうぞうしょしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.46502455,"lng":134.318832,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦及びスレート葺、建築面積276㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0106","desc":"主要地方道坂手港線の東側，山側に位置する左海醤油丘工場の敷地北方に西妻面を道路に見せて東西棟で建つ。桁行１７．６ｍ，梁間１０ｍ規模，桟瓦葺，切妻造の山側に桁行１１ｍ規模を延長する。杉板縦張の外壁上部に連子窓を並べた醤油蔵特有の外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002838"},{"id":"00002837","register_sub_id":"101","register_pk":"103827","name":"宝食品昆布蔵（旧左海醤油醸造所醤油蔵）","kana":"たからしょくひんこんぶぐら（きゅうさかいしょうゆじょうぞうしょしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字芦の浦2217-28","lat":34.464973,"lng":134.318527,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積408㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0105","desc":"主要地方道坂手港線の浜側に道路に沿って南北棟で建つ。桁行４０ｍ，梁間１０ｍ規模，桟瓦葺，切妻造で，現在は佃煮原料の貯蔵蔵として利用されているが，北妻面の「分銅・山サ」の屋号が由来を伝える。道路沿いに展開する「醤の里」景観の主要な構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002837"},{"id":"00002839","register_sub_id":"101","register_pk":"103829","name":"宝食品南佃煮原料蔵（旧左海醤油醸造所醤油蔵）","kana":"たからしょくひんみなみつくだにげんりょうぐら（きゅうさかいしょうゆじょうぞうしょしょうゆぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲2121-1","lat":34.464882,"lng":134.318771,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積242㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0107","desc":"左海醤油丘工場敷地南方に東西棟で建つ。桁行２２ｍ，梁間１１ｍ規模，桟瓦葺，切妻造で，東妻面は半切妻状に納める。敷地南辺沿いを流れる水路の花崗石の石積護岸を基礎とし，外壁は杉板張とする。「醤の里」景観の形成に貢献している建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002839"},{"id":"00010360","register_sub_id":"101","register_pk":"199132","name":"淡翁荘黒門","kana":"たんおうそうくろもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県坂出市本町1-3541-6","lat":34.31510095,"lng":133.85321609,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、間口2.4m、左右袖塀付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0400","desc":"淡翁荘主屋の北正面に建つ。一間一戸薬医門、切妻造本瓦葺で、五平の本柱を間口二・四二メートルで立て、欄間を盲連子とした両開き桟唐戸を吊り込む。両脇には瓦を載せた鉄筋コンクリート造の塀を矩折れにのばす。淡翁荘の表門として商店街側の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010360"},{"id":"00010359","register_sub_id":"101","register_pk":"199131","name":"淡翁荘主屋","kana":"たんおうそうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県坂出市本町1-3541-3他","lat":34.31494,"lng":133.853221,"geo_status":"db","era":"昭和11年／平成16年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積148㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0399","desc":"本店の西に建つ、もと鎌田醤油社長宅。外観は陸屋根、タイル張とした幾何学的で端正な意匠だが、内部は一階に上質な和風座敷、二階に暖炉を設えた本格的な洋室を配する。戦前期モダニズムの影響が認められ、県内の鉄筋コンクリート造住宅として最初期の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010359"},{"id":"00005039","register_sub_id":"101","register_pk":"106029","name":"丸尾醸造所原料蔵及び作業場","kana":"まるおじょうぞうしょげんりょうぐらおよびさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡94","lat":34.19153928,"lng":133.82904642,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0285","desc":"東主屋店舗部の南方に建つ作業場と，作業場の東側に並び建つ原料蔵で，ともに南北棟，切妻造，桟瓦葺の屋根をもち，小屋組は木造キングポストトラス。原料蔵は桁行１０間，梁間４間で，北方がもと米蔵で，南方が麹蔵となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005039"},{"id":"00005040","register_sub_id":"101","register_pk":"106030","name":"丸尾醸造所西味噌蔵","kana":"まるおじょうぞうしょにしみそぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県仲多度郡琴平町榎井字籏岡90-3","lat":34.19130552,"lng":133.82909018,"geo_status":"db","era":"大正中期／昭和初期増築","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"37 － 0286","desc":"小路を隔てた南敷地に位置し，北妻面を小路に見せて建つ。もと醤油諸味蔵で，桁行７間，梁間５間規模，南北棟，切妻造，桟瓦葺の２棟が並び建つ。東側は和小屋，西側は洋小屋である。北敷地の原料蔵とともに小路に醸造所特有の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005040"},{"id":"00000101","register_sub_id":"101","register_pk":"101091","name":"マルキン記念館（旧醤油醸造工場）","kana":"まるきんきねんかん（きゅうしょうゆじょうぞうこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.46698415,"lng":134.3192158,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1083㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0002","desc":"小豆島に建つ醤油醸造のための工場施設を転用した記念館。マルキンの印を妻に書き上部に明かり取り窓をとる外観に特徴があり，江戸時代後期以来醤油醸造で栄えた小豆島において，往時の景観を知る上で欠くことのできない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000101"},{"id":"00001957","register_sub_id":"101","register_pk":"102947","name":"マルキン醤油第五号発酵蔵","kana":"まるきんしょうゆだいごごうはっこうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.466995,"lng":134.32077,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積698㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"37 － 0056","desc":"第二号発酵蔵の西に並んで建ち，桁行が約２５メートル短いが構造形式は共通する。醤油天然醸造の工程を見せるため内部を公開しており，記念館として欠くことのできない建物であるとともに，工場施設の往時の景観を知る上で重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001957"},{"id":"00001956","register_sub_id":"101","register_pk":"102946","name":"マルキン醤油第四号発酵蔵","kana":"まるきんしょうゆだいよんごうはっこうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.46700231,"lng":134.320892,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積952㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"37 － 0055","desc":"桁行約９４メートルに及ぶ長大な醸造蔵で，工場の東辺を区切る位置に建つ。白壁に開けられた風通し窓が柱間一間毎に並ぶ外観に特徴があり，江戸時代後期以来醤油醸造で栄えた小豆島において，往時の景観を知る上で欠くことのできない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001956"},{"id":"00000102","register_sub_id":"101","register_pk":"101092","name":"マルキン醤油発酵蔵","kana":"まるきんしょうゆはっこうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽甲1850","lat":34.46649219,"lng":134.32027084,"geo_status":"db","era":"明治41～42","year":1908,"year_source":"converted","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1462㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0003","desc":"小豆島に建つ醤油醸造のための土蔵造の蔵。板を張った長大な妻を道路に面してみせる外観に特徴があり，記念館とともに江戸時代後期以来醤油醸造で栄えた小豆島において，往時の景観を知る上で欠くことのできない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000102"},{"id":"00003004","register_sub_id":"101","register_pk":"103994","name":"三谷製糖羽根さぬき本舗旧牛舎","kana":"みたにせいとうはねさぬきほんぽきゅうぎゅうしゃ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県東かがわ市馬宿156-6","lat":34.215431,"lng":134.419769,"geo_status":"db","era":"大正期／昭和初期移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積96㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0129","desc":"主屋西側敷地に東西棟で建つ。砂糖黍締車を引き回す牛の畜舎として建設。桁行１２ｍ，梁間４．５ｍ規模，切妻造，本瓦葺で，南北両面に下屋を差出し，北西部に角屋を張出す。板張の簡素な牛舎であるが，往事の和三盆の製造事情を物語る施設として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003004"},{"id":"00003003","register_sub_id":"101","register_pk":"103993","name":"三谷製糖羽根さぬき本舗砂糖釜屋","kana":"みたにせいとうはねさぬきほんぽさとうかまや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県東かがわ市馬宿156-5","lat":34.215226,"lng":134.41976776,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0128","desc":"主屋押し場玄関の南に取り付き，南北棟で建つ。桁行６ｍ，梁間５ｍ，切妻造，桟瓦葺の平屋建で，屋根上に煙出の越屋根と煉瓦煙突を建ち上げた釜屋ならではの外観を呈する。内部は，東半に大釜３連と小釜１基の煉瓦造竈を配置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003003"},{"id":"00003002","register_sub_id":"101","register_pk":"103992","name":"三谷製糖羽根さぬき本舗主屋（押し場）","kana":"みたにせいとうはねさぬきほんぽしゅおく（おしば）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県東かがわ市馬宿156-5","lat":34.21531949,"lng":134.41978163,"geo_status":"db","era":"大正期／昭和25頃増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"37 － 0127","desc":"阿讃国境大坂越峠下，菜切川左岸河口近くに位置し，阿讃街道から奥まったところに敷地を構える。南北棟，切妻造の２階建で，東面は下屋を差掛けてつし２階風に見せ，南方は平屋建として入母屋造とする。階下中央部は「押し場」で，天秤形状の圧搾機を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003002"},{"id":"00004033","register_sub_id":"101","register_pk":"105023","name":"元屋商店西醤油蔵及び東諸味蔵","kana":"もとやしょうてんにししょうゆぐらおよびひがしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町字城甲660-2","lat":34.4855688,"lng":134.18313865,"geo_status":"db","era":"明治初期／明治後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0198","desc":"主屋の北方に位置し東西棟で建つ。桁行１４間梁間４間，切妻造，桟瓦葺の東諸味蔵の東方桁行８間分は，明治１３年の家相図の醤油蔵に一致する。棟を高くした西方の桁行５間梁間５間規模の西醤油蔵とともに全長１９間の長大な醤油醸造蔵を敷地北辺に形づくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004033"},{"id":"00002834","register_sub_id":"101","register_pk":"103824","name":"ヤマサン醤油洗い場","kana":"やまさんしょうゆあらいば","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.4765311,"lng":134.3203208,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、面積28㎡及び10㎡、井戸付","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0102","desc":"醤油原料の洗い場で，花崗石を用いた井戸，花崗石敷の洗い場，排水溝から成る。東麹室西前面の作業広場南北に対として２箇所設置されており，北方は６．５ｍ×４．３ｍ，南方は３．６ｍ×２．８ｍ規模を有し，醤油醸造場特有の作業空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002834"},{"id":"00003623","register_sub_id":"101","register_pk":"104613","name":"ヤマサン醤油桶場","kana":"やまさんしょうゆおけば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47662073,"lng":134.32001817,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0180","desc":"槽場の西方に位置し，北醤油蔵の西妻面に接し，醸造場敷地北西辺に沿って建つ。桁行１５ｍ梁間６ｍ規模，切妻造，桟瓦葺の平屋建で，菱形平面とする点に特徴があり，醸造場側の南桁行面には下屋を差し掛けて錣屋根風にみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003623"},{"id":"00002832","register_sub_id":"101","register_pk":"103822","name":"ヤマサン醤油北醤油蔵","kana":"やまさんしょうゆきたしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47671828,"lng":134.32002921,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、瓦葺、建築面積546㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0100","desc":"醸造場敷地の北方に位置し，東西棟で建つ。桁行３０間，梁間５間規模，切妻造の長大な醤油醸造蔵で，内部梁間中央に１列の柱を建てる。現在は倉庫として利用されているが，かっては醸造用木桶１００基ほどが設置されていたと伝える。醤油醸造の中核的施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002832"},{"id":"00003621","register_sub_id":"101","register_pk":"104611","name":"ヤマサン醤油米蔵","kana":"やまさんしょうゆこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47659549,"lng":134.32038835,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0178","desc":"三階建工場の東方に位置し，ボイラー室と棟を並べて建つ。桁行８ｍ梁間３ｍ規模，南北棟，切妻造，桟瓦葺の平屋建で，南妻面の東寄りに庇付きの戸口を設け，北妻面の上部には小さな円形換気孔２口を開ける。洗い場などともに醸造場東側部を構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003621"},{"id":"00002831","register_sub_id":"101","register_pk":"103821","name":"ヤマサン醤油三階建醤油醸造工場","kana":"やまさんしょうゆさんかいだてしょうゆじょうぞうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47657631,"lng":134.32016548,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造3階建、瓦葺、建築面積56㎡","structure_material":"木造3階建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0099","desc":"醤油醸造場部のほぼ中央に位置する。桁行４間，梁間３間半規模，東西棟，桟瓦葺，切妻造の木造３階建で，小屋組はキングポストトラス，外壁は焼板縦張とする。他の醸造施設や住宅部よりひときわ高く，ヤマサン醤油のシンボルとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002831"},{"id":"00003620","register_sub_id":"101","register_pk":"104610","name":"ヤマサン醤油仕込み場及びボイラー室","kana":"やまさんしょうゆしこみばおよびぼいらーしつ","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47651231,"lng":134.3200959,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦葺、建築面積224㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0177","desc":"三階建工場の西面と南面に取り付くかたちで建つ。西から取り付く仕込み場は東西棟，切妻造，桟瓦葺の平屋建で，南桁行面に下屋を差し掛けて梁行１１ｍ規模とし，ボイラー室の屋根には換気のための越屋根を備える。小屋組はキングポストトラスを組む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003620"},{"id":"00005367","register_sub_id":"101","register_pk":"106355","name":"ヤマサン醤油製麹長屋門及び納屋","kana":"やまさんしょうゆせいきくながやもんおよびなや","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町馬木字内浜甲182-1","lat":34.47623086,"lng":134.31976466,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積92㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"37 － 0300","desc":"醤油醸造所及び醸造所主住宅の道路向いの敷地に建つ。道路沿いのへの字平面の平屋建納屋の東につし２階の長屋門が繋がる構成で，長屋門の西端に間口１間半規模の門口を開ける。長屋門の東方を麹室とし，南面に下屋庇を差し掛ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005367"},{"id":"00003622","register_sub_id":"101","register_pk":"104612","name":"ヤマサン醤油操作場","kana":"やまさんしょうゆそうさば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47648449,"lng":134.32044763,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0179","desc":"米蔵の南方，東麹室の西方に位置し，米蔵とは洗い場を介して向き合う。桁行南辺１１ｍ北辺１０ｍの台形平面で，梁間９ｍ規模。東西棟，切妻造，桟瓦葺の平屋建で，北面と西面に戸口を開け，屋根中央に越屋根を上げる。麹室に近接したもと釜場とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003622"},{"id":"00002833","register_sub_id":"101","register_pk":"103823","name":"ヤマサン醤油東麹蔵","kana":"やまさんしょうゆひがしこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47660897,"lng":134.32034538,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造平屋建、瓦葺、建築面積241㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"37 － 0101","desc":"北醤油蔵の南方，３階建工場の東方に作業広場を挟んで南北棟で建つ。桁行１５間規模で，内部は５室の麹室に分けられ，西面に１間幅の下屋を設けて戸前とする。北妻面には温度調節のため小窓を２箇所開ける。醤油醸造に欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002833"},{"id":"00003619","register_sub_id":"101","register_pk":"104609","name":"ヤマサン醤油槽場","kana":"やまさんしょうゆふなば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡小豆島町馬木字石井甲140-2","lat":34.47651607,"lng":134.31975564,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積245㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0176","desc":"醤油醸造元住宅屋敷地の北方に位置する醸造場敷地の北寄り，三階建工場と北醤油蔵の間に東西棟で建つ。桁行２５ｍ梁間１０ｍ規模の切妻造，桟瓦葺で，屋根西端近くに越屋根を載せる。内部は，柱や牛梁，地棟，束など丸太材による架構をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003619"},{"id":"00002464","register_sub_id":"101","register_pk":"103454","name":"山田家（旧清酒源氏正宗醸造元）煙突","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）えんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35340664,"lng":134.12971056,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、高さ18m","structure_material":"煉瓦造","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0080","desc":"主屋の北東方に建つ。高さ１８ｍ程の煉瓦造，イギリス積の角形煙突で，現在は独立して建ち，中程までをモルタル塗仕上げとする。上部には煉瓦を薄く刎ねだしてバンドを，頂部には歯飾状コーニスを造り出す。南面に「源氏正宗醸造元」の文字を書き記す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002464"},{"id":"00002462","register_sub_id":"101","register_pk":"103452","name":"山田家（旧清酒源氏正宗醸造元）北酒蔵","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）きたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35331,"lng":134.129822,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0078","desc":"主屋の東南方に位置し，南酒蔵の北方に接続して建つ。南北棟，切妻造，桟瓦葺，平入のもと酒蔵で，内部は南酒蔵と同様に食事室として活用されている。東面は下見板張の簡素な造りであるが，北方の煉瓦造煙突とともに造り酒屋の面影をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002462"},{"id":"00002459","register_sub_id":"101","register_pk":"103449","name":"山田家（旧清酒源氏正宗醸造元）主屋","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35327462,"lng":134.12960973,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積284㎡","structure_material":"木造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0075","desc":"四国霊場８５番札所八栗寺参道から７０ｍ程入った屋敷地のほぼ中央に南面して建つ。明治になって酒造業に転じた名家の居宅部で，桁行１４間と規模が大きく，入母屋造，本瓦葺，虫籠窓を開けたつし２階建とする。現在は「山田家」の屋号で讃岐うどん店を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002459"},{"id":"00002461","register_sub_id":"101","register_pk":"103451","name":"山田家（旧清酒源氏正宗醸造元）南酒蔵","kana":"やまだけ（きゅうせいしゅげんじまさむねじょうぞうもと）みなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"香川県","address":"香川県高松市牟礼町牟礼3186","lat":34.35318536,"lng":134.12988759,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、建築面積102㎡","structure_material":"土蔵造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0077","desc":"長屋門の東方に，南妻面を外周道路側に見せて建つ。南北棟，切妻造，桟瓦葺，平入のもと酒蔵で，西面に下屋を差し掛けて蔵前をとる。南面は腰部を板張，上部を白壁に仕上げ，東面は下見板張とする。内部は近年の改造により食事室に改められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002461"},{"id":"00003149","register_sub_id":"101","register_pk":"104139","name":"ヤマヒサ北諸味蔵","kana":"やまひさきたもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡小豆島町安田字新開甲243-1","lat":34.48102366,"lng":134.31399276,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0142","desc":"西諸味蔵の北西に位置し，南に双棟構えの南諸味蔵を接続させる。桁行１２間梁間５間規模，南北棟，切妻造，桟瓦葺の平屋建醤油蔵で，昭和７年創業時の施設。外観は西諸味蔵と同様の杉板張りとし北妻面に「山久」の屋号を印す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003149"},{"id":"00003148","register_sub_id":"101","register_pk":"104138","name":"ヤマヒサ西諸味蔵","kana":"やまひさにしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字新開甲243-1","lat":34.48087859,"lng":134.31382959,"geo_status":"db","era":"明治33／昭和24移築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0141","desc":"内海湾安田港の北方，内海郵便局東方の変形四叉路に南妻面を見せて建つ。桁行１０間梁間５間規模，南北棟，切妻造，桟瓦葺の平屋建醤油蔵で，東面に下屋を差掛ける。明治の醤油蔵を昭和２４年移築したもので，外観は当地の醤油蔵と同様に杉板張りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003148"},{"id":"00004036","register_sub_id":"101","register_pk":"105026","name":"やまひら醤油諸味蔵","kana":"やまひらしょうゆもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡土庄町大部字浜庄甲3260","lat":34.54558362,"lng":134.28384472,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"37 － 0201","desc":"大部港に北面する敷地の東北端に位置し東西棟で建つ。北面桁行２間半，南面桁行４間，梁間５間半の台形平面とした切妻造，桟瓦葺の醤油蔵で，小屋組はキングポストトラスとする。外装は腰を高い縦板張，上部を真壁造として街頭の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004036"},{"id":"00004667","register_sub_id":"101","register_pk":"105657","name":"山吉醤油圧搾場及び仕込場","kana":"やまよししょうゆあっさくばおよびしこみば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲710","lat":34.47536811,"lng":134.32465559,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺及びスレート葺、建築面積324㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0259","desc":"諸味蔵の東に平行し２棟並びで建つ。圧搾場は桁行１８ｍ梁間１０ｍ規模，切妻造，波形スレート葺，仕込場は桁行１４ｍ梁間８ｍ規模，切妻造，桟瓦葺で，ともに煙出しの越屋根を載せ，仕込場の東面に下屋庇を差し掛ける。諸味蔵とともに醤油醸造場の中心施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004667"},{"id":"00004669","register_sub_id":"101","register_pk":"105659","name":"山吉醤油釜屋","kana":"やまよししょうゆかまば","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲709-2","lat":34.47551,"lng":134.32463166,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡、煙突付","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0261","desc":"原料蔵の東方，水路を隔てた圧搾場及び仕込場の北方に位置し，東西棟で建つ。桁行１８ｍ梁間６ｍ規模，切妻造，桟瓦葺の木造平屋建で，棟の中央西寄りに煙出しを載せ，煙出し西側に煉瓦造煙突を突き出す。煙突は高さ１５ｍで，山吉醤油のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004669"},{"id":"00004668","register_sub_id":"101","register_pk":"105658","name":"山吉醤油原料蔵及び帳場","kana":"やまよししょうゆげんりょうぐらおよびちょうば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲709-2","lat":34.475517,"lng":134.32449155,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0260","desc":"水路を隔てた諸味蔵の北方に位置し，南北棟で建つ。桁行８．２ｍ梁間７．７ｍ規模，切妻造，桟瓦葺の木造２階建で，東面に下屋庇を添わす。外部は諸味蔵と同様に，腰焼杉縦板張，上部白漆喰塗とし，諸味蔵とともに醤油醸造所特有の景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004668"},{"id":"00004666","register_sub_id":"101","register_pk":"105656","name":"山吉醤油諸味蔵","kana":"やまよししょうゆもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字今坂甲710","lat":34.4753388,"lng":134.32447634,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"37 － 0258","desc":"屋敷地を横断する水路の南方，離れ屋の北方に南北棟で建つ。桁行２４ｍ梁間１０ｍ規模，切妻造，桟瓦葺の木造平屋建で，南半には諸味桶を据え，北半は瓶詰場とする。外部は腰焼杉縦板張，上部白漆喰塗とし，南半には高窓を並べ，北半の棟には煙出しを上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004666"},{"id":"00003626","register_sub_id":"101","register_pk":"104616","name":"ヤマロク醤油西諸味蔵","kana":"やまろくしょうゆにしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字空条甲1607","lat":34.48630104,"lng":134.32109093,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺及びスレート葺、建築面積131㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0183","desc":"東諸味蔵の西に接して建つ。桁行１５．５ｍ梁間７．３ｍ規模，南北棟，切妻造，波形スレート葺で，北妻面に桁行３．６ｍの下屋を差し掛けて蔵前をとる。東諸味蔵とともに２棟並びの妻面をみせ，醸造場敷地南辺道路沿いに独特の醤油蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003626"},{"id":"00003625","register_sub_id":"101","register_pk":"104615","name":"ヤマロク醤油東諸味蔵","kana":"やまろくしょうゆひがしもろみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県小豆郡小豆島町安田字空条甲1607","lat":34.48627186,"lng":134.3211908,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、スレート葺、建築面積85㎡","structure_material":"土蔵造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"37 － 0182","desc":"内海湾に南流する安田大川の東方に位置する醸造場敷地の東寄りに建つ。桁行１０．４ｍ梁間８．２ｍ規模であるが，桁行は２／３ほどに切り縮められている。南北棟の切妻造で，南妻面を東西道路にみせ，簡素な虫籠窓を２箇所に開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003625"},{"id":"00002699","register_sub_id":"101","register_pk":"103689","name":"旭醤油醸造場","kana":"あさひしょうゆじょうぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県宇和島市吉田町東小路甲112","lat":33.27932723,"lng":132.53997712,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造平屋建、瓦葺、建築面積113㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0026","desc":"町中心部の街路の角地に建つ。瘤出仕上の花崗岩基礎の上に，切妻造平入，土蔵造躯体を立上げ，正面に格子を嵌めた横長の窓と，瀟洒な鉄製持送り付の小庇を設ける。店舗部分には醤油の量売りに用いたタイル張の流しを残す。大正期の街路景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002699"},{"id":"00002182","register_sub_id":"101","register_pk":"103172","name":"梅錦山川主屋","kana":"うめにしきやまかわしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県四国中央市金田町金川14","lat":33.98914992,"lng":133.59390661,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"38 － 0013","desc":"川之江から高知に抜ける旧道に西面して建つ。造り酒屋の店舗兼住宅主屋で，ほぼ南半をシモテ，北半をカミテとする。入母屋造，本瓦葺，つし２階風の重厚かつ長大な構えを旧道からややひいた位置に展開し，仕込蔵とともに地区のランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002182"},{"id":"00004055","register_sub_id":"101","register_pk":"105045","name":"梅美人酒造釜場及び煙突","kana":"うめびじんしゅぞうかまばおよびえんとつ","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46540086,"lng":132.42571594,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0056","desc":"事務所の西方に位置し，東西棟で建つ。切妻造，桟瓦葺で，小屋組はキングポストトラスとし，換気用の越屋根を上げる。西妻面の南寄りには正方形断面の煉瓦造煙突を建ち上げ，南面に「ウメビジンホン店」を表す。港からの格好のランドマークになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004055"},{"id":"00004056","register_sub_id":"101","register_pk":"105046","name":"梅美人酒造醸造場","kana":"うめびじんしゅぞうじょうぞうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県八幡浜市1557-2","lat":33.46548993,"lng":132.42584589,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積767㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0057","desc":"敷地西辺沿いの南北棟の仕込蔵と，釜場北面に沿う東西棟の貯蔵蔵とがＴ字形の棟構成をつくる。仕込蔵内部の２階北方には麹室がつくられ，貯蔵蔵の１階北西隅を槽場に充てる。ともに創業以来の施設で，醸造場の核となる建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004056"},{"id":"00005202","register_sub_id":"101","register_pk":"106192","name":"遠登志橋","kana":"おとしばし","category":"産業2次","subcategory":"土木構造物","type_guess":"橋","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県新居浜市立川町620-1地先","lat":33.89079217,"lng":133.31142796,"geo_status":"db","era":"明治38／平成4改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"鋼製単アーチ橋、橋長48m、幅員2.4m","structure_material":"鋼製単アーチ橋","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0066","desc":"市内山間部を南北に貫流する国領川水系小女郎川に架かる。坑水路兼道路橋として別子鉱山内に築かれた橋長４８ｍ，スパン３７ｍの鋼製スパンドレルブレースト単アーチ橋。アーチにはⅠ型鋼を用い両端をピン支承で固定する。わが国現存最古級の鋼製アーチ橋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005202"},{"id":"00013463","register_sub_id":"101","register_pk":"368559","name":"旧住友化学工業株式会社幹部社宅","kana":"きゅうすみともかがくこうぎょうかぶしきがいしゃかんぶしゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1896-1","lat":33.94914167,"lng":133.26093056,"geo_status":"db","era":"昭和10年／平成30年改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積275㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0147","desc":"新居浜市北西部に位置する住友山田社宅の西部に建つ。木造平屋建、瓦葺で、外壁は下見板張とする。東寄りは北東隅を玄関、南東隅を洋室の応接間とし、その西側は、南を客間、北を居間、台所等とする。中央の畳廊下で、公用と私用の空間を分けた幹部の社宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013463"},{"id":"00013465","register_sub_id":"101","register_pk":"368561","name":"旧住友共同電力株式会社監査役社宅","kana":"きゅうすみともきょうどうでんりょくかぶしきがいしゃかんさやくしゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1857-1","lat":33.94968889,"lng":133.26005556,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積173㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0149","desc":"新居浜市北西部に位置する住友山田社宅の西部に建つ。木造平屋建、桟瓦葺で、外壁は吹付塗装とする。東端中央を玄関、南に応接室、西に床、棚付の客間を配す。北側中央は内玄関で、西半を私用空間とする。東半を客用、西半を私用に分けた企業監査役の社宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013465"},{"id":"00013464","register_sub_id":"101","register_pk":"368560","name":"旧住友共同電力株式会社幹部社宅","kana":"きゅうすみともきょうどうでんりょくかぶしきがいしゃかんぶしゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1900","lat":33.94944444,"lng":133.26012778,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積295㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0148","desc":"新居浜市北西部に位置する住友山田社宅の西部に建つ。木造平屋建、桟瓦葺で、外壁は竪羽目板張、上部小壁を漆喰塗仕上とする。北東隅を玄関、ホールを介し南に洋室の応接間、その西側に１０畳と６畳の客間を配す。東半を客用、西半を私用に分けた幹部社宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013464"},{"id":"00013459","register_sub_id":"101","register_pk":"368544","name":"旧住友鉱業株式会社別子鉱業所長社宅応接棟","kana":"きゅうすみともこうぎょうかぶしきがいしゃべっしこうぎょうしょちょうしゃたくおうせつとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1903-1","lat":33.9498,"lng":133.26123333,"geo_status":"db","era":"昭和12年／平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0143","desc":"主屋北面西寄に渡廊下で接続して建つ。木造平屋建、切妻造桟瓦葺で、東面に入母屋屋根を二段突出して玄関とする。外壁は真壁漆喰塗で、腰は下見板張。内部は東半に玄関、渡廊下等を、西半に洋風の応接室、広縁を配す。主屋と一連で、端正な造りを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013459"},{"id":"00013458","register_sub_id":"101","register_pk":"368543","name":"旧住友鉱業株式会社別子鉱業所長社宅主屋","kana":"きゅうすみともこうぎょうかぶしきがいしゃべっしこうぎょうしょちょうしゃたくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1903-1","lat":33.94968889,"lng":133.26133056,"geo_status":"db","era":"昭和12年／平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0142","desc":"市北西部の住友山田社宅西部にある敷地中央に北面して建つ。横長の入母屋造桟瓦葺で、棟東端南北面に千鳥破風を、南面に下屋を付す。内部は雁行した廊下を通し、南側に床付座敷等の居室を、北側に玄関、家政部を並べる。華美さを抑えた端正かつ上質な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013458"},{"id":"00013460","register_sub_id":"101","register_pk":"368545","name":"旧住友鉱業株式会社別子鉱業所長社宅茶室","kana":"きゅうすみともこうぎょうかぶしきがいしゃべっしこうぎょうしょちょうしゃたくちゃしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1903-1","lat":33.94961111,"lng":133.26148333,"geo_status":"db","era":"昭和12年／平成30年改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0144","desc":"主屋南東に接続し、切妻造桟瓦葺の水回り及び前室部と、南端の切妻造桟瓦葺で三方に下屋を廻した茶室からなる。茶室は８畳の座敷で、南、西面に縁を廻す。東面の床は、一間半幅の地袋の上に床柱を立てて明障子を開くなど、自由な造作を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013460"},{"id":"00013462","register_sub_id":"101","register_pk":"368558","name":"旧住友別子鉱山株式会社外国人技師西社宅","kana":"きゅうすみともべっしこうざんかぶしきがいしゃがいこくじんぎしにししゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1900","lat":33.94976667,"lng":133.26046389,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積130㎡","structure_material":"木造2階建一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0146","desc":"東社宅の西側に建つ。木造2階建、切妻造桟瓦葺で、南に寄棟造のサンルームを突出し、西に片流屋根の家政部を付す。外壁は下見板張。東社宅に類似したＬ字型居室配置の平面を成すが、やや小振りにつくる。会社の業態転換に伴う外国人技師招聘の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013462"},{"id":"00013461","register_sub_id":"101","register_pk":"368557","name":"旧住友別子鉱山株式会社外国人技師東社宅","kana":"きゅうすみともべっしこうざんかぶしきがいしゃがいこくじんぎしひがししゃたく","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県新居浜市星越町乙1900","lat":33.94994722,"lng":133.26077222,"geo_status":"db","era":"昭和5年／昭和前期・同中期増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建一部平屋建、瓦葺、建築面積196㎡","structure_material":"木造2階建一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"38 － 0145","desc":"市北西部の住友山田社宅西部にある。木造2階建、寄棟造桟瓦葺で、南に突出した寄棟造のサンルームは掃出窓で開放的につくり、西に平屋建の家政部を付す。外壁は下見板張。内部は上下階共南東の大部屋を中心にＬ字型に３室配す。洋風意匠で端正にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013461"},{"id":"00014113","register_sub_id":"101","register_pk":"508373","name":"旧二宮製材所事務所兼主屋","kana":"きゅうにのみやせいざいしょじむしょけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県喜多郡内子町小田360","lat":33.57066667,"lng":132.80420556,"geo_status":"db","era":"昭和17年／同40年代改修","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積145㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"38 - 0162","desc":"内子町東部の山間の町に位置する林業家の町家。通りに東面する入母屋造平入桟瓦葺。北に土間、南は東半を一室の事務所、西半は三室続き座敷とする。北に炊事場棟、南に浴室・便所棟を突出する。二階は建ちを押さえつつ四方に出桁で軒を持出し、豪壮にみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014113"},{"id":"00003721","register_sub_id":"101","register_pk":"104711","name":"旧三崎精錬所焼窯","kana":"きゅうみさきせいれんしょやきかま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西宇和郡伊方町佐田乙2085","lat":33.36306339,"lng":132.10361684,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造、建築面積496㎡","structure_material":"石造","registered":"2003.12.01(平成15.12.01)","register_no":"38 － 0050","desc":"町南部，宇和海に面する山の斜面に築かれる。荒吹と呼ばれる銅の製錬作業に用いられる窯が，煙道と共に斜面の上方向に直線状に横３列，曲線状に２列配され，各焚口を緑泥変岩を用いて直径０．９ｍ程のアーチでつくる。銅製錬の近代化を知る上で貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003721"},{"id":"00004059","register_sub_id":"101","register_pk":"105049","name":"佐々木酒造煉瓦煙突","kana":"ささきしゅぞうれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県伊予郡砥部町総津785","lat":33.62829135,"lng":132.79807098,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ20m","structure_material":"煉瓦造","registered":"2004.03.02(平成16.03.02)","register_no":"38 － 0060","desc":"主屋南西に位置する醸造蔵の南端に建つ。基部は煉瓦長手６枚半四方で，緩やかなカーブを描いて逓減し，煉瓦の持ち出し技法により特徴的な柱頭飾り風の頂部をつくる。高さ２０ｍ規模で，国道からも容易く確認することができ，地区の目印的存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004059"},{"id":"00012070","register_sub_id":"101","register_pk":"211011","name":"正木本店会所場・釜場・煙突","kana":"まさきほんてんかいしょば・かまば・えんとつ","category":"産業2次","subcategory":"建築物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228444,"lng":132.706724,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"会所・窯場 木造平屋建、瓦葺、建築面積145㎡ 煙突 煉瓦造、高さ14m","structure_material":"会所・窯場 木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"38-121","desc":"貯蔵庫と仕込庫の入隅に建つ。貯蔵庫西面で釜場が接し、北に一二畳半の会所場を張り出し、全体に切妻造の屋根を大きく架ける。釜場内に建つ煙突は、一辺一・八メートルの正方形平面をもつ煉瓦造で高さ一四メートルあり、酒造場に相応しい景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012070"},{"id":"00012069","register_sub_id":"101","register_pk":"211010","name":"正木本店生酒庫","kana":"まさきほんてんきしゅこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228354,"lng":132.706434,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積225㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"38-120","desc":"仕込庫の北に東西棟で平行する。桁行一三・五間、梁間四間、平屋建で、東に梁間二間の検査室を張り出す。屋根は切妻造、桟瓦葺とする。小屋組はキングポストトラスとし、筋交や方杖で補強し、広い梁間を構成する。安定した採光を確保するため北面に窓を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012069"},{"id":"00012068","register_sub_id":"101","register_pk":"211009","name":"正木本店仕込庫","kana":"まさきほんてんしこみこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228396,"lng":132.706553,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積274㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"38-119","desc":"貯蔵庫の西に東西棟で直交する。桁行一二間、梁間六間、二階建で、屋根は切妻造、桟瓦葺とする。内部は、一室で、一階階高は四メートルあり、中央二列に直径二七センチメートルで磨き丸太のままのスギ材の柱を二間毎に立て二階床組を支える大規模な仕込庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012068"},{"id":"00012067","register_sub_id":"101","register_pk":"211008","name":"正木本店貯蔵庫","kana":"まさきほんてんちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228528,"lng":132.706784,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、瓦葺、建築面積266㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"38-118","desc":"店舗部の北に続く貯蔵庫。梁間四間で、桁行一一間半の平屋建部と桁行四間の二階建部からなり、いずれも切妻造、桟瓦葺である。内部は一室で鉄骨の梁を用いて小屋組を造る。外壁は漆喰塗腰板張で、塗込の格子窓を要所に穿ち、街路からの景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012067"},{"id":"00012066","register_sub_id":"101","register_pk":"211007","name":"正木本店店舗兼主屋","kana":"まさきほんてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県北宇和郡松野町大字松丸86","lat":33.228444,"lng":132.706998,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積324㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"38-117","desc":"松丸街道沿いに南面する。店舗部は切妻造で、正面一階に格子を構え、二階は塗込め窓を連続し、内部は土間吹抜けに豪壮な梁組をみせる。座敷部は入母屋造で下屋庇を廻らし、内部に三室を並べる。異なる意匠の外観を巧みに連ね、街道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012066"},{"id":"00011424","register_sub_id":"101","register_pk":"209261","name":"水口酒造店舗兼主屋","kana":"みなくちしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県松山市道後喜多町975","lat":33.851371,"lng":132.782633,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積260㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"38－0114","desc":"道後温泉の近傍で、通りに北面して建つ造酒屋の店舗兼主屋。右土間とし、床上部の正面側には帳場を構える。二階には二四畳半の大広間を備え、小屋組はこの大広間直上のみトラス、ほかを和小屋とする。柱と貫を現しとした外観が、町並みの風情を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011424"},{"id":"00010522","register_sub_id":"101","register_pk":"199462","name":"旧浜口家住宅主屋","kana":"きゅうはまぐちけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高岡郡佐川町字西町甲1472-1","lat":33.498824,"lng":133.288242,"geo_status":"db","era":"明治初期／大正6・平成25改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積217㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"39 － 0279","desc":"酒造業を営んだ旧家の主屋。吹抜の通り土間の左右に部屋を並べ、東奧に八畳の座敷を配する。土間まわりは網代の壁や天井を用い、座敷の違棚には梅鉢紋入りの精緻な飾金具を飾る。正面は長屋門を思わせる重厚な外観に出格子を並べ、通りの歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010522"},{"id":"00006723","register_sub_id":"101","register_pk":"107706","name":"豊永染物店蔵","kana":"とよながそめものてんくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田1899","lat":33.43939519,"lng":133.98272076,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0233","desc":"安田川に東面する敷地の東寄りに建つ。桁行２間半梁間２間の土蔵造２階建、南北棟で、西に下屋をつけて蔵前とする。屋根は切妻造で、左桟瓦と右桟瓦を用いる。外壁は土佐漆喰塗で妻面に３段の水切り瓦を見せ、腰を板張とする。川辺景観の要素として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006723"},{"id":"00006724","register_sub_id":"101","register_pk":"107707","name":"豊永染物店土塀","kana":"とよながそめものてんどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田1899","lat":33.43953081,"lng":133.98263942,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"練塀、瓦葺、延長14m","structure_material":"練塀","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0234","desc":"敷地北辺を限る塀。もと水路であった道に沿って彎曲し、延長１４ｍを測る。人頭大の石を赤土で積んだ練塀で、基底幅０．６ｍ。総高１．６ｍで、道の東下り勾配に合わせ、中途で１段低く造る。上部は桟瓦葺とする。伝統的な工法により特色ある景観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006724"},{"id":"00003734","register_sub_id":"101","register_pk":"104724","name":"濱川家住宅蔵","kana":"はまかわけじゅうたくくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡田野町字西町1880-1","lat":33.42759695,"lng":134.01006443,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積193㎡","structure_material":"土蔵造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0091","desc":"田野町中心地に位置し，敷地南寄りに東妻面を道路に見せて建つ。桁行１０間梁間３間，東西棟，切妻造，桟瓦葺で，北面に切妻造の入口部と下屋を差し掛ける。軒下の高い位置に窓を並べ，当地方特有の土佐漆喰塗壁に水切瓦を廻して長大な壁面をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003734"},{"id":"00010521","register_sub_id":"101","register_pk":"202577","name":"濵川商店酒蔵","kana":"はまかわしょうてんさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡田野町字橋本西2150-1","lat":33.426222,"lng":134.008261,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造2階建、瓦葺、建築面積347㎡、煉瓦造煙突付","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"39 － 0278","desc":"川に面して建つ土蔵造二階建、切妻造桟瓦葺で片面下屋付の大規模な酒蔵。一階を仕込蔵、二階を麹室及び酒母室とする。下屋には倉庫と大竈、煉瓦煙突を据え、日本酒の工程一式を一棟に収める。川側は換気用窓を並べ、多段に廻らせる水切が土佐の蔵の特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010521"},{"id":"00001966","register_sub_id":"101","register_pk":"102956","name":"濱田家住宅（旧増田屋）蔵","kana":"はまだけじゅうたく（きゅうますだや）くら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡奈半利町乙1751","lat":33.42609703,"lng":134.02220691,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積83㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0016","desc":"大蔵と並び建つ桁行約１４ｍ，梁行約４ｍ規模の長い土蔵で，桁行約７．２ｍ分の北蔵と，棟を落とした南蔵から成り，北蔵と南蔵との間を蔵前とし，東面に一体的な下屋を付ける。北蔵は，置屋根型式で，北と東面は水切瓦をつけるなど整った意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001966"},{"id":"00001964","register_sub_id":"101","register_pk":"102954","name":"濱田家住宅（旧増田屋）主屋","kana":"はまだけじゅうたく（きゅうますだや）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡奈半利町乙1751","lat":33.42587505,"lng":134.02215464,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積167㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0014","desc":"旧道の一等地に建つ寛政７年（１７９５）創業の造り酒屋と質屋を営んだ商家。間口約１０ｍ，奥行約１５ｍ規模，切妻造，桟瓦葺，２階建，平入で，正面に下屋庇を付ける。西妻面及び正面２階に水切瓦を付けるなど奈半利における商家建築の代表的事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001964"},{"id":"00001961","register_sub_id":"101","register_pk":"102951","name":"藤村製絲株式会社石塀","kana":"ふじむらせいしかぶしきがいしゃいしべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2630","lat":33.42825636,"lng":134.02484907,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"石造、延長35m","structure_material":"石造","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0011","desc":"敷地の西辺を限る丸石練塀。５０ｃｍ厚，高さ２．２ｍで，南部は玉石，北部は半割面を見せ，頂部に桟瓦葺の小屋根を載せる。土佐地方特有の「いしぐろ」の系統を引くが，基礎を間知積風，コーナーを切石積とするなど近代の手法も採り入れられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001961"},{"id":"00001958","register_sub_id":"101","register_pk":"102948","name":"藤村製絲株式会社西蔵","kana":"ふじむらせいしかぶしきがいしゃにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県安芸郡奈半利町乙2630","lat":33.42847711,"lng":134.02506502,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積190㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"39 － 0008","desc":"奈半利川河口左岸に位置し，捕鯨や林業で栄えた奈半利の実業家である藤村米太郎が興した製糸工場の繭蔵で，敷地の西北隅に建つ。桁行約１６ｍ，梁間約１０ｍ規模の東西棟，切妻造，桟瓦葺，平入２階建土蔵で，妻面には当地方特有の水切瓦を５段に付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001958"},{"id":"00004072","register_sub_id":"101","register_pk":"105062","name":"松岡家住宅北酒蔵","kana":"まつおかけじゅうたくきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53207699,"lng":133.35195645,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積128㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0140","desc":"槽場の北側に接し敷地奥に位置する。桁行８間梁間４間の規模を有する，土蔵造２階建，東西棟，切妻造，桟瓦葺，平入の土蔵で，他の酒蔵と同様に左瓦を用いる。外装は土壁で，北側の腰を羽目板付きの板張とし，基部には石を据える。屋敷内で最大規模の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004072"},{"id":"00004074","register_sub_id":"101","register_pk":"105064","name":"松岡家住宅西酒蔵","kana":"まつおかけじゅうたくにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53190429,"lng":133.35185808,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積98㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0142","desc":"屋敷地の西端に位置する。南北棟，切妻造，桟瓦葺で，東酒蔵と並び建ち，東酒蔵内部から平側の入口に導かれる。桁行７間梁間４間規模の平屋建で，外周壁はバットレス付きのＲＣ造壁とする。酒蔵構造の発展過程を物語る遺構。他の酒蔵同様左瓦を使用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004074"},{"id":"00004073","register_sub_id":"101","register_pk":"105063","name":"松岡家住宅東酒蔵","kana":"まつおかけじゅうたくひがしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53190747,"lng":133.3519805,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0141","desc":"槽場の正面西側で槽場とＬ字型に接続する。桁行５間梁間３間半の土蔵造平屋建，桟瓦葺で，南北棟の切妻造，平入とし，前面に下屋を１間張り出し，内部北半を西酒蔵への通路に供する。外装は土佐漆喰塗，一部板張。醸造所敷地を取り囲む主要構成要素の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004073"},{"id":"00004071","register_sub_id":"101","register_pk":"105061","name":"松岡家住宅槽場","kana":"まつおかけじゅうたくふなば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高岡郡日高村本郷1887","lat":33.53198262,"lng":133.35199927,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積189㎡","structure_material":"土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0139","desc":"主屋の西側に位置し，東西棟で建つ。桁行８間梁間３間の木造２階建，切妻造，桟瓦葺，平入で，南面に下屋を張り出す。内部の東側を槽場とし，西側の３間四方に麹室を造る。外装は正面を土佐漆喰塗，妻面を土壁とする。屋根に左瓦を用いるのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004071"},{"id":"00003473","register_sub_id":"101","register_pk":"104463","name":"松尾酒造北酒蔵","kana":"まつおしゅぞうきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.60376405,"lng":133.68030197,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積107㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0076","desc":"主屋の南方に位置し，敷地東辺に沿って南北棟で建つ。桁行８間，梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，麹室として建設。 外観は，妻破風を縦板張で覆い，１階を縦板張，２階を白漆喰塗壁とし，東側道路に造り酒屋特有の酒蔵景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003473"},{"id":"00003474","register_sub_id":"101","register_pk":"104464","name":"松尾酒造西酒蔵","kana":"まつおしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.6035681,"lng":133.68022092,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造平屋建、瓦葺、建築面積113㎡","structure_material":"土蔵造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0077","desc":"北酒蔵の西南方に位置し，東西棟で建つ。桁行８間，梁間４間，切妻造，桟瓦葺の平屋建土蔵で，仕込蔵として建設。現在は「松翁酒造りとくらしの資料室」とする。外装は白漆喰塗で，土佐特有の水切り瓦を２段に廻しているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003474"},{"id":"00003475","register_sub_id":"101","register_pk":"104465","name":"松尾酒造南酒蔵","kana":"まつおしゅぞうみなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県香美市土佐山田町西本町5-1","lat":33.60360325,"lng":133.6803709,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"39 － 0078","desc":"北酒蔵の南方，西酒蔵の東南方に位置し，東妻面を道路にみせて東西棟で建つ。桁行５間，梁間３間規模，切妻造，桟瓦葺の２階建土蔵で，貯蔵蔵として建設。東面は北酒蔵と同様に腰を縦板張，妻破風を縦板張で覆い，南面には水切り瓦を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003475"},{"id":"00004184","register_sub_id":"101","register_pk":"105174","name":"陽和工房登窯","kana":"ようわこうぼうのぼりがま","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸市井ノ口乙3472","lat":33.53688582,"lng":133.91277974,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"煉瓦造、奥行20m、幅7m","structure_material":"煉瓦造","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0149","desc":"文化文政頃より始まった内原野焼という陶器窯元の施設。緩やかな斜面に築かれた全長２０ｍ，幅７ｍ，６房からなる連房式登窯で，粘土でかたちづくり，内外に焼粘土塊を張付けて整える。江戸後期の数少ない登窯として，地域の産業史を物語る稀少な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004184"},{"id":"00008597","register_sub_id":"101","register_pk":"134993","name":"石蔵酒造事務所兼主屋","kana":"いしくらしゅぞうじむしょけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区堅粕1-3-6","lat":33.59871415,"lng":130.41750613,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積204㎡、煙突付","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0061","desc":"通りの北側に位置する。間口一八メートルの二階建町家で、桁行に西から土間、事務室、居室の三部分に分かれ、屋根も入母屋と切妻の複雑な構成となる。一階に平格子、二階に漆喰仕上げの大壁に銅板貼の両開戸を設けるなど、意匠性豊かな表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008597"},{"id":"00008598","register_sub_id":"101","register_pk":"134994","name":"石蔵酒造主倉","kana":"いしくらしゅぞうしゅぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福岡市博多区堅粕1-3-6","lat":33.59886456,"lng":130.41765654,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積974㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0062","desc":"事務所兼主屋の北に位置する。東西棟の切妻造桟瓦葺で、南・北面全面に下屋を付設。桁行三九メートル、梁間は併せて二六メートルに及ぶ。妻面は下見板張とし、鉢巻などを漆喰で仕上げる。二階建で、トラス組が豊かな内部空間をつくる。大規模な酒造倉の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008598"},{"id":"00008599","register_sub_id":"101","register_pk":"134995","name":"石蔵酒造西倉及び旧精米所","kana":"いしくらしゅぞうにしくらおよびきゅうせいまいじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市博多区堅粕1-3-6","lat":33.59908264,"lng":130.41743093,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積429㎡、渡廊下、煙突及び釜場付","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0063","desc":"敷地の西隅に位置する。通り沿いの旧精米所とその北の西倉からなり、事務所への渡り廊下を付設する。いずれも切妻造桟瓦葺で、西面妻は下見板張、南面は腰高に下見板を張り、上部漆喰仕上げ。下見板の黒色と漆喰の白の鮮やかな対比が趣ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008599"},{"id":"00013895","register_sub_id":"101","register_pk":"507853","name":"浦野醤油醸造元主屋","kana":"うらのしょうゆじょうぞうもとおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県豊前市大字八屋1341-1","lat":33.61696111,"lng":131.117375,"geo_status":"db","era":"明治40年／昭和49年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積217㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0187","desc":"中津街道八屋宿の中心部に所在する二階建入母屋造妻入桟瓦葺の商家。二階は観音開き扉や隅石積の漆喰塗で意匠を凝らし、一階は雨戸を備えた開放的な間口としてミセを構え、下手は通り土間、上手は前庭に面した座敷とする。街道宿の面影を伝える豪壮な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013895"},{"id":"00013896","register_sub_id":"101","register_pk":"507854","name":"浦野醤油醸造元塀","kana":"うらのしょうゆじょうぞうもとへい","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県豊前市大字八屋1341-1","lat":33.61706389,"lng":131.11746111,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、延長4.8m、潜門付","structure_material":"木造","registered":"2021.06.24(令和3.06.24)","register_no":"40 － 0188","desc":"主屋正面の北角から通りに沿って北に延びる桟瓦葺の塀で、通りと前庭を区切る。延長四・八メートルで、一間毎に柱を立て南から第二間に両開き板戸の門を構える。ほかは漆喰塗真壁として欄間を開け、腰はモルタル塗。主屋と一連で旧街道宿場町の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013896"},{"id":"00010704","register_sub_id":"101","register_pk":"201278","name":"勝屋酒造煙突","kana":"かつやしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県宗像市赤間4-957","lat":33.80478611,"lng":130.58929448,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造、高さ13m","structure_material":"煉瓦造","registered":"2015.08.04(平成27.08.04)","register_no":"40－0133","desc":"店舗兼主屋の後方西寄りに位置する煉瓦造の煙突である。基底部は一辺一・〇メートルの正六角形平面で、高さ一三メートルを測る。躯体はイギリス積を基本として頂部とその下方に蛇腹を廻らし、隅部に山形鋼を添えて補強する。酒造場らしいランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010704"},{"id":"00010703","register_sub_id":"101","register_pk":"201277","name":"勝屋酒造店舗兼主屋","kana":"かつやしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県宗像市赤間4-957","lat":33.80476873,"lng":130.58937583,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、瓦葺、建築面積190㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0132","desc":"旧唐津街道に面し、前面に下屋を通す。外壁は漆喰塗込めで両隅に隅石を表す。上下階の前面に格子をたて、下屋の軒を繰形付の腕木で持ち出す。右手に通り土間を配して左手を二列の居室とし、もとミセの事務室や座敷を配する。宿場の面影を伝える造酒屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010703"},{"id":"00010706","register_sub_id":"101","register_pk":"201280","name":"寒北斗酒造安政の蔵","kana":"かんほくとしゅぞうあんせいのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県嘉麻市大隈町字入地1036-1他","lat":33.547489,"lng":130.743946,"geo_status":"db","era":"安政4年（1857）／明治前期改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積199㎡","structure_material":"土蔵造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0135","desc":"主屋後方に建つ、桁行二二メートル梁間七メートルの長大な土蔵造二階建で、切妻造桟瓦葺である。平側に出入口を開けて下屋を設ける。一階は無柱の大空間を確保し、小屋組は、管柱上の小梁で受ける丑梁に登り梁を架けて組む。建築年代の明らかな幕末の酒蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010706"},{"id":"00010707","register_sub_id":"101","register_pk":"201281","name":"寒北斗酒造仕込蔵","kana":"かんほくとしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県嘉麻市大隈町字入地1036-1他","lat":33.547527,"lng":130.744226,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積272㎡","structure_material":"土蔵造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0136","desc":"敷地南東隅に建つ仕込蔵。桁行二〇メートル梁間一四メートルと大規模で、切妻造桟瓦葺である。外壁は漆喰塗で腰に竪板を張り、窓を千鳥に配して表情を創る。キングポストトラスを採用して無柱の大空間を実現し、近代的発展を示す酒蔵で、街路景観にも寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010707"},{"id":"00010705","register_sub_id":"101","register_pk":"201279","name":"寒北斗酒造店舗兼主屋","kana":"かんほくとしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県嘉麻市大隈町字入地1036-1他","lat":33.547661,"lng":130.743841,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積404㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0134","desc":"秋月街道沿いの造酒屋。入母屋造妻入の外部を鼠漆喰で塗込め、重厚な外観を見せる。左手を広い土間、右手に事務所や中の間等を並べ、さらに右側面の前後に角座敷を張出して中庭を囲み、発展的平面を示す。上質な客間をもつ幕末の酒造所施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010705"},{"id":"00010702","register_sub_id":"101","register_pk":"201276","name":"旧出光家住宅主屋","kana":"きゅういでみつけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県宗像市赤間4-888","lat":33.805828,"lng":130.590347,"geo_status":"db","era":"明治26年／昭和中期改修","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0131","desc":"旧唐津街道に面する町家で、左手の土間部は屋根を落棟とする。中央の通り土間の右手にミセ、中の間などを並べ、中の間は吹抜けとして上部に高欄を飾る。旧の土間は広く、藍甕が据えられていた。正面柱筋に摺上戸を残すなど、赤間宿の町家の形態をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010702"},{"id":"00014976","register_sub_id":"101","register_pk":"519236","name":"旧國武合名会社倉庫","kana":"きゅうくにたけごうめいがいしゃそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市日吉町字三丁目117-1","lat":33.31588889,"lng":130.51609444,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木骨煉瓦造2階建、瓦葺、建築面積134㎡","structure_material":"木骨煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0222","desc":"久留米旧城下に位置する久留米絣の旧商品庫。二階建切妻造平入桟瓦葺。外壁を鉱滓煉瓦の小口積とする木骨煉瓦造で中央西寄りにアーチの入口を開け、正面に鉄扉を吊る。内部は各階板敷で和小屋を現す。正面アーチに社標を掲げ、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014976"},{"id":"00014975","register_sub_id":"101","register_pk":"519235","name":"旧國武合名会社綿糸部店舗及び倉庫","kana":"きゅうくにたけごうめいがいしゃめんしぶてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市日吉町字二丁目71-4","lat":33.31609722,"lng":130.51568333,"geo_status":"db","era":"大正11年／昭和前期、平成27年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造一部木骨煉瓦造2階建、瓦葺、建築面積151㎡","structure_material":"木造一部木骨煉瓦造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0221","desc":"久留米旧城下に位置する久留米絣製造販売業の旧店舗及び倉庫。角地に建つ木造二階建入母屋造桟瓦葺南北棟で北に木骨煉瓦造東西棟の倉庫を接続する。旧店舗は西と南に腕木を重ねた出桁庇を廻らす豪壮な外観とし、旧倉庫は西妻に社標を掲げてアクセントとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014975"},{"id":"00006661","register_sub_id":"101","register_pk":"107644","name":"旧上妻家住宅（津屋崎千軒民俗館藍の家）井戸屋形","kana":"きゅうこうづまけじゅうたく（つやざきせんげんみんぞくかんあいのいえ）いどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎4-935","lat":33.78940048,"lng":130.46308431,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、桧皮葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"40 － 0058","desc":"主屋の東背面、裏庭の中央に位置する。井戸枠は方１．０ｍの人造石研出し仕上げで、四隅に内転びの柱を立て、六角屋根を架ける。屋根は檜皮で葺き、竹で押さえる。西面と北面に壁があり、それぞれ円形と方形の下地窓を開く。数寄屋風意匠をもつ遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006661"},{"id":"00006660","register_sub_id":"101","register_pk":"107643","name":"旧上妻家住宅（津屋崎千軒民俗館藍の家）主屋","kana":"きゅうこうづまけじゅうたく（つやざきせんげんみんぞくかんあいのいえ）しゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎4-935","lat":33.789452,"lng":130.463028,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積156㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"40 － 0057","desc":"通りに西面する木造２階建の平入町家。桁行６間梁間４間半の切妻造桟瓦葺で、表裏に庇が付き、背面に渡廊下で便所が接続。正面中央の戸口の両脇を格子で飾る。２階壁は白漆喰塗で、窓枠を塗り出す。内部は南が土間で北に喰違いに５室を配す。明治期町家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006660"},{"id":"00006286","register_sub_id":"101","register_pk":"107270","name":"旧サッポロビール九州工場組合棟","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうくみあいとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-103他","lat":33.905949,"lng":130.931732,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積108㎡","structure_material":"煉瓦造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0048","desc":"醸造棟の北側に近接して建つ。桁行１２ｍ，梁間９ｍ規模で，煉瓦造平屋建，切妻造，鉄板葺とする。床を地盤面より１．７ｍ高くつくる。北面に扉口を開き，周囲にアーチ窓を開く。柱形を外に見せ，要に石材を使い，妻壁にパラペットを立上げ，重厚な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006286"},{"id":"00006284","register_sub_id":"101","register_pk":"107268","name":"旧サッポロビール九州工場事務所棟","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-104","lat":33.906219,"lng":130.931763,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積232㎡、塔屋付","structure_material":"煉瓦造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0046","desc":"関門海峡沿いの国道１９９号東側敷地に西面して建つ。桁行１９ｍ，梁間１４ｍで，煉瓦造２階建とする。正面中央玄関部を突出させ塔状に３階高まで立ち上げ，１・２階共に左右対称の意匠として中心性を強調する。鉱滓煉瓦を使用し，細部意匠にも工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006284"},{"id":"00006285","register_sub_id":"101","register_pk":"107269","name":"旧サッポロビール九州工場醸造棟","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうじょうぞうとう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-103他","lat":33.905724,"lng":130.931366,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建・3階建・4階建及び7階建、鉄板葺，建築面積1180㎡","structure_material":"煉瓦造2階建・3階建・4階建及び7階建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0047","desc":"事務所棟の南側に建つ。南北５５ｍ，東西２７ｍの規模の煉瓦造で，２階建，３階建，４階建，７階建の建物をほぼコの字状に連結して並べ，周囲にアーチ窓を開く。ビールの製造工程に従って高さの異なる建物が組み合わされ，大規模な特徴のある多様な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006285"},{"id":"00006287","register_sub_id":"101","register_pk":"107271","name":"旧サッポロビール九州工場倉庫","kana":"きゅうさっぽろびーるきゅうしゅうこうじょうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県北九州市門司区大里本町3-6-103他","lat":33.90649037,"lng":130.93141798,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積1050㎡","structure_material":"煉瓦造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"40 － 0049","desc":"事務所棟の道路を隔てて西側に建つ。桁行３３ｍ，梁間２９ｍの規模で，煉瓦造２階建，切妻造，鉄板葺を並列に２連に並べる。妻面に扉口を開き，上部を円形窓としていた。小屋組はクイーンポスト形式で，倉庫の大空間を確保している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006287"},{"id":"00014977","register_sub_id":"101","register_pk":"519237","name":"九州建具木工所倉庫","kana":"きゅうしゅうたてぐもっこうじょそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津124他","lat":33.20634167,"lng":130.37070556,"geo_status":"db","era":"昭和31年／平成元年頃改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積308㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0223","desc":"木工業で繁栄した筑後川河口の小保に建つ木工所の倉庫。切妻造妻入で正面二階中央に四連の縦長窓を開け、前面に迫出しパラペットを立上げる。小屋組は対束間の母屋を束で受けた変則的なクイーンポスト・トラス。モダンな外観が戦後の木工業の繁栄を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014977"},{"id":"00006467","register_sub_id":"101","register_pk":"107450","name":"旧三井田川鉱業所伊田竪坑第一煙突","kana":"きゅうみついたがわこうぎょうしょいだたてこうだいいちえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川市大字伊田2734-1","lat":33.64033218,"lng":130.81515919,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ45m","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"40 － 0052","desc":"竪坑櫓より約１２０ｍ南方に位置する。旧汽罐場に付属する高さ４５ｍ（１５０尺）の煉瓦造円形煙突で、全体をイギリス積で精緻に築き、基部には半円アーチ形の煙道を一部残す。現存する明治期の煉瓦煙突として最大級の規模を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006467"},{"id":"00006491","register_sub_id":"101","register_pk":"107474","name":"旧三井田川鉱業所伊田竪坑第二煙突","kana":"きゅうみついたがわこうぎょうしょいだたてこうだいにえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川市大字伊田2734-1","lat":33.64039073,"lng":130.8150041,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"煉瓦造、高さ45m","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"40 － 0053","desc":"第一煙突から約２５ｍ西に位置する。旧汽罐場に付属する高さ４５ｍ（１５０尺）の煉瓦造煙突で、全体をイギリス積で築き、基部を八角形断面、他の部分を円形断面とする。竪坑、第一煙突と共に「炭鉱節」に謡われた構造物として知られ、筑豊の繁栄の歴史を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006491"},{"id":"00006466","register_sub_id":"101","register_pk":"107449","name":"旧三井田川鉱業所伊田竪坑櫓","kana":"きゅうみついたがわこうぎょうしょいだたてこうやぐら","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県田川市大字伊田2734-1","lat":33.64146314,"lng":130.814993,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"鉄骨造、高さ28m","structure_material":"鉄骨造","registered":"2007.10.02(平成19.10.02)","register_no":"40 － 0051","desc":"市のほぼ中心部に位置する旧鉱山施設。Ⅰ形鋼を用いた４本の鋼柱等からなる鋼構造体の頂部に、２基の大型ヘッドシーブを据え付けて総高２８ｍとし、西側にはバックステイを添える。筑豊に残る唯一の鋼製櫓で、現存する明治期の竪坑櫓として最大級の規模を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006466"},{"id":"00010528","register_sub_id":"101","register_pk":"199468","name":"ジョーキュウ醤油裏座敷","kana":"じょーきゅうしょうゆうらざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-1","lat":33.587894,"lng":130.394971,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0120","desc":"敷地西辺、表座敷の北側に建つ。木造二階建で一階の三方に下屋の廊下を廻らし、上下階とも座敷二室を配する。一階の座敷飾は平書院の手前に略三角形の棚板を付けて付書院風に見せ、また床脇の地袋、天袋を台形平面とするなど昭和期らしい凝った意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010528"},{"id":"00010533","register_sub_id":"101","register_pk":"199473","name":"ジョーキュウ醤油煙突","kana":"じょーきゅうしょうゆえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-4","lat":33.587874,"lng":130.395294,"geo_status":"db","era":"大正4／平成17改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、高さ9.5m、面積2.5㎡","structure_material":"煉瓦造","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0125","desc":"敷地南東の火入れ場に残る煉瓦造煙突。底部は一辺六七センチメートルの八角形平面で基礎を二段に迫り出し、高さ九・五メートルである。躯体はイギリス積で、久留米の荒木窯業の施工と伝わる。震災で高さを減じているが醸造所を象徴する施設として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010533"},{"id":"00010527","register_sub_id":"101","register_pk":"199467","name":"ジョーキュウ醤油表座敷","kana":"じょーきゅうしょうゆおもてざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-1","lat":33.5878,"lng":130.395006,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積44㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0119","desc":"敷地南西隅に位置する木造二階建、切妻造桟瓦葺の接客用座敷で、南北に下屋を設けて縁とする。上下階とも二室の座敷からなり、一階の南室を八畳主室として座敷飾を備え、二階北室は窓辺に高欄を設ける。醸造所の一隅を占める、良質な接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010527"},{"id":"00010530","register_sub_id":"101","register_pk":"199470","name":"ジョーキュウ醤油米蔵","kana":"じょーきゅうしょうゆこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-3","lat":33.587974,"lng":130.395026,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0122","desc":"納戸蔵の東、敷地の中央に建つ二階建土蔵。南北棟で、南の中庭に向けて銅板葺の庇を付けた出入口を設ける。内部の壁は板張、小屋組は登梁形式として、二階の南北に窓をあける。現在は醤油醸造に使用する道具類を納めており、醸造所の敷地景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010530"},{"id":"00010531","register_sub_id":"101","register_pk":"199471","name":"ジョーキュウ醤油仕込蔵","kana":"じょーきゅうしょうゆしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県福岡市中央区大名1-330-3","lat":33.587985,"lng":130.39509,"geo_status":"db","era":"文久2(1862)","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積123㎡","structure_material":"土蔵造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"40 － 0123","desc":"敷地の中央、米蔵の東側に南北棟で建つ大型の土蔵で、切妻造桟瓦葺である。建ちの高い平屋建で、南半部には仕込み桶の上から作業ができるよう仮設的な床を張る。和小屋の小屋組の下に天井を張る。仕込蔵の特徴をよく備えた、醤油醸造所を象徴する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010531"},{"id":"00002098","register_sub_id":"101","register_pk":"103088","name":"鶴味噌並倉北棟","kana":"つるみそなみくらきたとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県柳川市三橋町江曲216","lat":33.1607939,"lng":130.40921087,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積62㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"40 － 0016","desc":"三橋町と柳川市との境を流れる掘割に沿って建つ。煉瓦造平屋建，切妻造桟瓦葺の旧麹室で，鋸歯飾りをあしらった胴蛇腹，妻面に円形換気窓を設ける。中棟との間に設けた庇部に，妻面に合わせて煉瓦壁を延ばし，半円アーチ形の開口部を穿つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002098"},{"id":"00002099","register_sub_id":"101","register_pk":"103089","name":"鶴味噌並倉中棟","kana":"つるみそなみくらなかとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県柳川市三橋町江曲216","lat":33.16074311,"lng":130.40921404,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"煉瓦造平屋建、瓦葺、建築面積45㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"40 － 0017","desc":"３棟の内，煉瓦造蔵として最初に建てられたと伝わる。妻面を木造横板貼とし，フランス積の壁面に北・南棟で模される櫛形アーチ開口部を２箇所設ける。登梁を中柱で支えた和小屋を載せる。他棟と類似しつつ，微妙に変化をもつ外観が水辺景観を豊かにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002099"},{"id":"00002100","register_sub_id":"101","register_pk":"103090","name":"鶴味噌並倉南棟","kana":"つるみそなみくらみなみとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県柳川市三橋町江曲216","lat":33.16068712,"lng":130.40921548,"geo_status":"db","era":"明治39頃／大正7増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積70㎡","structure_material":"煉瓦造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"40 － 0018","desc":"北棟と類似した外観。キングポストトラスの小屋組を載せ，小規模な切妻屋根を冠す中棟との間隙に煉瓦壁を築き，鋸歯飾りの胴蛇腹によって主棟との連続性を持つ。３棟の煉瓦妻面が掘割に面する並倉は，水郷柳川の歴史的景観形成に大きく寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002100"},{"id":"00010699","register_sub_id":"101","register_pk":"201273","name":"松岡家住宅玄関門","kana":"まつおかけじゅうたくげんかんもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2","lat":33.423175,"lng":130.583249,"geo_status":"db","era":"嘉永3年（1850）／大正12年頃移築","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"40－0128","desc":"主屋の入母屋玄関の前方に、西向きに構える門。間口二・二メートル、一間薬医門、切妻造桟瓦葺である。軸部はクスノキを主材とし、冠木上に矩形の梁を三筋渡して疎垂木の軒を受ける。左右にのびる煉瓦塀とともに、風格のある庭空間を創出する表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010699"},{"id":"00010697","register_sub_id":"101","register_pk":"201271","name":"松岡家住宅主屋","kana":"まつおかけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2","lat":33.423235,"lng":130.583306,"geo_status":"db","era":"大正12年／昭和50年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積380㎡","structure_material":"木造平屋一部2階建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0126","desc":"南面する主体部は建ちの高い入母屋造妻入で正面に入母屋玄関を構える。西端の土間の高い吹抜けでは幾重にも組上げた力感ある梁組を現すなど重厚な軸組になる。また東側に張出す十五畳の広間は銘木を用いて上質な造作としており、当地の大型民家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010697"},{"id":"00010698","register_sub_id":"101","register_pk":"201272","name":"松岡家住宅倉庫","kana":"まつおかけじゅうたくそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2","lat":33.423382,"lng":130.583334,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"40－0127","desc":"主屋後方に張出す配膳室に接続して東西棟で建つ。桁行一四メートル梁間四メートル、切妻造桟瓦葺で、東寄りに換気用の越屋根を設ける。外壁は真壁漆喰塗で腰に竪板を張り、内部東寄りで二室に仕切る。従業員の食堂などに使われた建物で酒造場の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010698"},{"id":"00010701","register_sub_id":"101","register_pk":"201275","name":"松岡家住宅塀","kana":"まつおかけじゅうたくへい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2他","lat":33.42311,"lng":130.58317,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"煉瓦造、総延長89m","structure_material":"煉瓦造","registered":"2015.08.04(平成27.08.04)","register_no":"40－0130","desc":"主屋の前庭を囲み、敷地南面に折曲がりにのびる煉瓦塀で総延長八九メートルを測る。江戸切仕上げの花崗岩積基礎の上に鉱滓煉瓦をイギリス積とし、頂部に軒蛇腹三段積と屋根二段積を施す。特に敷地南西隅は円弧状平面として技巧的に仕上げ集落景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010701"},{"id":"00010700","register_sub_id":"101","register_pk":"201274","name":"松岡家住宅門柱","kana":"まつおかけじゅうたくもんちゅう","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県小郡市干潟字中屋敷645-2他","lat":33.423146,"lng":130.583163,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造門柱2基、間口4.5m","structure_material":"石造門柱2基","registered":"2015.08.04(平成27.08.04)","register_no":"40－0129","desc":"主屋南東隅西側の通路入口に位置し、花崗岩製の門柱一対を間口四・五メートルに立てる。石柱は一辺四五センチメートル、高さ三・五メートルの江戸切仕上げとし、柱天に帯状の飾りを付ける。酒造場への入口をなしていた門柱で、往時の敷地景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010700"},{"id":"00013667","register_sub_id":"101","register_pk":"504611","name":"吉原家住宅主屋及び角座敷","kana":"よしはらけじゅうたくおもやおよびつのざしき","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津107-2-2他","lat":33.20572778,"lng":130.37113889,"geo_status":"db","era":"主屋 江戸後期、角座敷 天保9年(1838)／昭和中期以前・同63年・平成6年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積333㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0183","desc":"大川市小保の旧街道沿いに東面して建つ。主屋は二階建切妻造桟瓦葺妻入で、四周に庇を廻し正面に下屋を付す。漆喰を軒先まで塗込め、内部は北を土間、南を床上部とする。南に平屋建切妻造の角座敷を接続し玄関を付す。小保の町並を代表する大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013667"},{"id":"00013668","register_sub_id":"101","register_pk":"504612","name":"吉原家住宅煉瓦塀","kana":"よしはらけじゅうたくれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県大川市大字小保字中ノ船津107-2-2他","lat":33.20575833,"lng":130.37121111,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、延長6.3m","structure_material":"煉瓦造","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0184","desc":"主屋の東南角から通りに沿って南に延びる煉瓦造の塀。延長六メートルで、高さ二メートルの規模である。煉瓦は平目地として、頂部は軒蛇腹で飾り、煉瓦で屋根を造る。主屋の東南の腰壁にも煉瓦が積まれて一連の景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013668"},{"id":"00009862","register_sub_id":"101","register_pk":"195691","name":"天吹酒造旧蔵人用炊事場煙突","kana":"あまぶきしゅぞうきゅうくらびとようすいじばえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32670159,"lng":130.4574745,"geo_status":"db","era":"明治後期／昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ7.3m","structure_material":"煉瓦造","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0091","desc":"主屋北面東寄りに建つ煉瓦煙突で、イギリス積とする。基部の平面は一・二メートル角で、高さは七・三メートルである。腰部に帯状の迫出しを設け、東面基部に欠円アーチの焚き口を作る。もと従業員賄い用の釜屋に附属していた煙突で、蔵元の生活様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009862"},{"id":"00009863","register_sub_id":"101","register_pk":"195692","name":"天吹酒造旧酒造蔵煙突","kana":"あまぶきしゅぞうきゅうしゅぞうぐらえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字村副2290-1","lat":33.32633754,"lng":130.45760001,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0092","desc":"貯蔵庫（旧白米倉庫）の北側に建つ煉瓦煙突。煉瓦造、イギリス積で、基部の平面は直径一・四メートルの六角形とし、高さは一一メートルを測る。腰部と頂部に装飾的な帯状部を設け、東面基部に欠円アーチの焚き口を作る。酒造場を象徴する煉瓦煙突である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009863"},{"id":"00009858","register_sub_id":"101","register_pk":"195687","name":"天吹酒造仕込蔵","kana":"あまぶきしゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32714893,"lng":130.45749472,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積665㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0087","desc":"主屋後方に南北棟で建つ。桁行三九メートル梁間一七メートル、土蔵造二階建、妻入、桟瓦葺で、南北面に下屋を設ける。外壁は軒先まで漆喰塗込めとし、腰を竪板張とする。内部柱に太い丸太を使い、小屋は登り梁と和小屋を併用する。雄大な規模の仕込蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009858"},{"id":"00009855","register_sub_id":"101","register_pk":"195684","name":"天吹酒造主屋","kana":"あまぶきしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32663021,"lng":130.45745189,"geo_status":"db","era":"明治中期／明治34改修、大正期増築、昭和後期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階一部3階建、瓦葺、建築面積315㎡","structure_material":"木造2階一部3階建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0084","desc":"北側敷地の南端に南面し、木造二階一部三階建、入母屋造桟瓦葺で、外壁は漆喰塗とする。内部は中央に土間を通し、東半に既存の土蔵を取込み、事務所や応接間を配する。西半の床上部は東西二列に仏間や座敷などの居室を並べる。伝統的な住宅形式を伝る主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009855"},{"id":"00009859","register_sub_id":"101","register_pk":"195688","name":"天吹酒造地下貯蔵庫","kana":"あまぶきしゅぞうちかちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32715369,"lng":130.45727105,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"鉄筋コンクリート造平屋建、建築面積477㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0088","desc":"北側敷地北西の斜面地に東西棟で建ち、東妻の入口は地上に開くが、西側は地中となる。桁行三〇メートル梁間一六メートル、鉄筋コンクリート造平屋建で、内部は南北二室に区分され、各々東妻に出入口を設ける。現在も冷蔵庫として使用されている貯蔵施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009859"},{"id":"00009857","register_sub_id":"101","register_pk":"195686","name":"天吹酒造貯蔵庫（旧麹室）","kana":"あまぶきしゅぞうちょぞうこ（きゅうこうじむろ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.3267468,"lng":130.45755897,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦造及び木造平屋建、瓦葺、建築面積78㎡","structure_material":"煉瓦造及び木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0086","desc":"主屋北東側に東西棟で建つ。桁行一六メートル梁間五メートル、南面煉瓦造、北面木造、平屋建、切妻造桟瓦葺で、西妻面を戸口として瓦庇を付す。南面は煉瓦壁を現し、北面竪板張とする。内部は一室で小屋は和小屋を組む。特異な軸部構成の貯蔵庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009857"},{"id":"00009860","register_sub_id":"101","register_pk":"195689","name":"天吹酒造貯蔵庫（旧白米倉庫）","kana":"あまぶきしゅぞうちょぞうこ（きゅうはくまいそうこ）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32623522,"lng":130.45760894,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積113㎡","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0089","desc":"南側敷地の北寄りに南北棟で建つ。桁行一四メートル梁間六・一メートル、土蔵造平屋建、切妻造桟瓦葺で、西面に吹放しの下屋を設ける。外壁漆喰塗で、腰は東面を海鼠壁、西面は竪板張とする。内部は一室で小屋は和小屋を組む。田園風景に白壁が映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009860"},{"id":"00009856","register_sub_id":"101","register_pk":"195685","name":"天吹酒造離れ座敷","kana":"あまぶきしゅぞうはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32677298,"lng":130.45733292,"geo_status":"db","era":"大正期／昭和中期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0085","desc":"主屋北西部に接続する。木造平屋建、入母屋造桟瓦葺で、周囲に下屋を廻らす。八畳主室の北側にトコ、床脇、付書院を備え、南東に縁を配す。南側に張出す二畳の小間にも小振りの座敷飾を設け、円窓を穿つ。開放的な室内構成で、造作も瀟洒な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009856"},{"id":"00009861","register_sub_id":"101","register_pk":"195690","name":"天吹酒造瓶詰工場（旧仕込蔵）","kana":"あまぶきしゅぞうびんづめこうじょう（きゅうしこみぐら）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県三養基郡みやき町大字東尾字東尾2894","lat":33.32598776,"lng":130.45762797,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建、瓦葺、建築面積561㎡","structure_material":"木造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"41 － 0090","desc":"南側敷地の南端に南北棟で建つ。桁行四〇メートル梁間一四メートル、木造二階建、切妻造桟瓦葺で、北面を下屋とする。外壁漆喰塗で腰高に竪板を張り、軒下に高窓を並べる。小屋は登り梁と和小屋を併用する。酒造場の表構えを引き立てる大規模建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009861"},{"id":"00005677","register_sub_id":"101","register_pk":"106665","name":"飯盛酒造一号蔵及び二号蔵","kana":"いいもりしゅぞういちごうぐらおよびにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09204848,"lng":130.11393641,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積365㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0061","desc":"敷地の南辺に沿って土蔵造２階建の一号蔵が建ち，東の麹室との間を木造平屋建，片流れ屋根の二号蔵が繋ぐ。一号蔵は桁行１０間，梁間６間の切妻造桟瓦葺で，外壁を竪羽目板張で覆う。小屋組は束立の和小屋である。二号蔵は台形平面でトラス小屋組とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005677"},{"id":"00005680","register_sub_id":"101","register_pk":"106668","name":"飯盛酒造煙突","kana":"いいもりしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09231045,"lng":130.11408841,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造、高さ9m","structure_material":"煉瓦造","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0064","desc":"主屋の東側，釜場の北側に位置する。主屋土間の外壁に沿うように建つ煉瓦造煙突である。一辺約１．５ｍの正方形で，高さ約９ｍ。鉄製の補強枠が取り付けられている。飯盛家が取得する以前の醸造銘柄「玉の香」の文字が北面に残る。酒蔵通りを象徴する遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005680"},{"id":"00005679","register_sub_id":"101","register_pk":"106667","name":"飯盛酒造麹室","kana":"いいもりしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09212174,"lng":130.11408445,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"煉瓦造平屋建、瓦葺、建築面積49㎡","structure_material":"煉瓦造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0063","desc":"敷地の南東角に位置する煉瓦造平屋建である。三号蔵の南面に接続し，敷地形状に合わせて西面がやや開いた台形平面を持つ。桁行４間，梁間３間規模の南北棟で，切妻造，桟瓦葺の洋風トラス小屋組の木造屋根を架ける。敷地東側の景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005679"},{"id":"00005678","register_sub_id":"101","register_pk":"106666","name":"飯盛酒造三号蔵","kana":"いいもりしゅぞうさんごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市古枝甲122","lat":33.09222062,"lng":130.11401812,"geo_status":"db","era":"大正末期／昭和初期増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建、瓦葺、建築面積151㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0062","desc":"敷地の東辺，主屋土間の裏手に建つ土蔵造２階建である。南に麹室が接続する。桁行５間，梁間は４間で西側に２間幅を葺下ろした切妻造，桟瓦葺とする。小屋組は束立の和小屋である。槽場及び瓶詰め場として使われた。西側に下屋で検査室と休憩所を増築した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005678"},{"id":"00014124","register_sub_id":"101","register_pk":"508384","name":"旧枝梅酒造店舗兼主屋","kana":"きゅうえだうめしゅぞうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市八戸一丁目124-2","lat":33.24737222,"lng":130.27799167,"geo_status":"db","era":"江戸末期／平成30年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積200㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0126","desc":"旧長崎街道に南面する造り酒屋の町家。二階建寄棟造桟瓦葺平入で背後に棟を延ばし、全体にコの字の屋根とする。正面は下屋を付し、ニ階は軒まで塗込める。内部は東を土間、西を二列五室とする。佐賀特有のくど造の様相を伝え、建ちが低く全体に古式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014124"},{"id":"00004190","register_sub_id":"101","register_pk":"105180","name":"旧杵島炭鉱大鶴鉱業所第二坑口","kana":"きゅうきしまたんこうおおづるこうぎょうしょだいにこうぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"隧道・坑口","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県唐津市肥前町大字入野甲1-3","lat":33.45078328,"lng":129.83470219,"geo_status":"db","era":"昭和11頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"コンクリート造及び煉瓦造、間口7.0m","structure_material":"コンクリート造及び煉瓦造","registered":"2004.06.09(平成16.06.09)","register_no":"41 － 0044","desc":"石炭搬出のため建造された。コンクリート造で，坑門と約７ｍの坑道からなる。坑門は両端部を柱型とし，凸状頂部にはコーニスをつけ，中央に直径約４ｍの半円形坑口を開き，表面は洗い出し仕上げとする。田園地帯にあって，炭鉱施設の一端を今に伝える構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004190"},{"id":"00004473","register_sub_id":"101","register_pk":"105463","name":"呉竹酒造一番蔵","kana":"くれたけしゅぞういちばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2751","lat":33.092224,"lng":130.117355,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積483㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0050","desc":"主屋の東に棟を並べて建つ。南北棟，入母屋造，桟瓦葺，妻入の２階建酒蔵で，桁行９間梁間８間規模。中央を作業場とし，主屋寄りの西側に米洗所・釜場などを配し，東面に東西棟の精米所と南北棟の麹室を付属する。改造はあるが，酒造場の中核となる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004473"},{"id":"00004474","register_sub_id":"101","register_pk":"105464","name":"呉竹酒造東の蔵","kana":"くれたけしゅぞうひがしのくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2751","lat":33.09242747,"lng":130.11735287,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積591㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0051","desc":"主屋及び一番蔵の北方に位置し，敷地北辺道路に沿って東西棟で建つ。桁行１８間梁間７間規模，切妻造，桟瓦葺，平入の２階建仕込蔵で，西側を貯蔵庫と分析試験室，東側を槽場に充てる。北面外部は高い腰部を縦板張，上部を白漆喰塗として小窓を３段に開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004474"},{"id":"00013768","register_sub_id":"101","register_pk":"505333","name":"光栄菊酒造洗い場及び釜場","kana":"こうえいぎくしゅぞうあらいばおよびかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29938889,"lng":130.22613333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 115","desc":"通り蔵の北に軸を振って接続する。木造平家建切妻造桟瓦葺で南北棟の洗い場と釜場を東西に並べ、南北に谷樋を通す。西面に開口を多くとり、洗い場の屋根に採光窓を設ける。釜場の大釜は土間を掘込んで据え、外部の煙突に接続する。酒造施設の一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013768"},{"id":"00013772","register_sub_id":"101","register_pk":"505341","name":"光栄菊酒造煙突","kana":"こうえいぎくしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29938333,"lng":130.22624167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ11m","structure_material":"煉瓦造","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 119","desc":"釜場の東に位置。一・七メートル四方、高さ一・六メートルの煉瓦造基壇上に総高約一一メートルを煉瓦造イギリス積で積む。上方に向けて先細りし、最上部の煙口に四段の繰形を付ける。四方の隅部は鉄枠で補強する。地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013772"},{"id":"00013771","register_sub_id":"101","register_pk":"505339","name":"光栄菊酒造旧麹室","kana":"こうえいぎくしゅぞうきゅうこうじむろおよびつうろ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.2991,"lng":130.22648333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 118","desc":"本蔵の東、ムロマエの南面に接続。木造平屋建切妻造桟瓦葺で、水路石積上に御影石の布基礎を廻し、高さ三メートルまで煉瓦積の壁を木造軸組の外面に化粧で現す。上部は竪板張で南面上部に開口を開ける。小屋組はキングポストトラス。敷地南東の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013771"},{"id":"00013767","register_sub_id":"101","register_pk":"505331","name":"光栄菊酒造通り蔵及び本蔵","kana":"こうえいぎくしゅぞうとおりぐらおよびほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29919444,"lng":130.22626389,"geo_status":"db","era":"通り蔵 大正9年／昭和11年改修、本蔵 昭和2年／昭和11年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積955㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 114","desc":"小城市の旧街道に面する酒造施設。木造二階建半切妻造桟瓦葺で南北棟の通り蔵と本蔵を東西に並べ、南端で接続してコの字形平面をなす。本蔵北に下屋付属。各蔵とも二列の独立柱を立て、吹抜の接続部は豪壮な小屋組をみせる。南面の大屋根が景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013767"},{"id":"00013770","register_sub_id":"101","register_pk":"505337","name":"光栄菊酒造ムロマエ","kana":"こうえいぎくしゅぞうむろまえ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29920833,"lng":130.22647778,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 117","desc":"本蔵の東、モトクラの南面に接続。木造平屋建両下造桟瓦葺。外部は腰を竪板張とし、上部は現在下見板張とするが旧は漆喰仕上。布基礎の上に煉瓦を数段積み柱を立てる。内部は二階の床組を一部残し小屋組は二重梁和小屋。施設内最古で酒造施設の歴史上重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013770"},{"id":"00013769","register_sub_id":"101","register_pk":"505335","name":"光栄菊酒造モトクラ","kana":"こうえいぎくしゅぞうもとくら","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市三日月町織島字下七本六割2602-3","lat":33.29935,"lng":130.22645556,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"41 － 116","desc":"本蔵東面北端に接続。木造平屋建北面半切妻造南面切妻造で桟瓦葺。御影石の布基礎、土台上に柱を立て、外壁は竪板張。北・東面は一間毎に掃出窓を設け北面上部に水切庇付きの開口を開く。内部は二階の床組を残し小屋組は二重梁和小屋。敷地北東の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013769"},{"id":"00002717","register_sub_id":"101","register_pk":"103707","name":"小柳酒造煙突","kana":"こやなぎしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29874649,"lng":130.20257123,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"煉瓦造、高さ17m","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0032","desc":"釜場南妻面西端の前に建つ。１．８ｍ角，高さ１６．５ｍ，上にいくほどすぼまる形態のイギリス積煉瓦造煙突で，頂部はバンドを廻しモルタル塗仕上げとする。昭和西蔵の棟高をはるかに越え，周囲に造り酒屋の存在を知らしめる格好のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002717"},{"id":"00002716","register_sub_id":"101","register_pk":"103706","name":"小柳酒造釜場","kana":"こやなぎしゅぞうかまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29881342,"lng":130.2026424,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0031","desc":"昭和西蔵の東に接して建つ。桁行１１ｍ，梁間９ｍ規模，南北棟，桟瓦葺，切妻造の平屋建で，棟中央に換気用の越屋根を載せる。外壁は縦羽目を主とし，南妻には繊細なキングポストトラスの架構を見せて東蔵北妻面とは対照的な表情を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002716"},{"id":"00002725","register_sub_id":"101","register_pk":"103715","name":"小柳酒造検査室","kana":"こやなぎしゅぞうけんさしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1、904-1","lat":33.29867319,"lng":130.20248844,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0040","desc":"昭和西蔵の南方に建つ。桁行５．４ｍ，梁間３．６規模，東西棟，桟瓦葺，切妻造の木造平屋建で，東妻に入口を設ける。外観は，下見板張りとし，南，東，北の３面に引違いガラス窓を建込む。昭和初期酒税検査の様子の一端を窺い知ることのできる施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002725"},{"id":"00002722","register_sub_id":"101","register_pk":"103712","name":"小柳酒造麹室","kana":"こやなぎしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29890586,"lng":130.20226149,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0037","desc":"敷地の西北隅部に位置する。桁行１１ｍ，梁間６．５ｍ規模で，東西棟，切妻造，桟瓦葺とする。木造，平屋建で，外観は縦羽目板張とするが，入口のある正面妻側は梁下までイギリス積の煉瓦壁とする特異な造りとなる。造り酒屋にとって欠くことのできない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002722"},{"id":"00002714","register_sub_id":"101","register_pk":"103704","name":"小柳酒造昭和西蔵","kana":"こやなぎしゅぞうしょうわにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.298889,"lng":130.202438,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積431㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0029","desc":"主屋の西方，水路を隔てた醸造場敷地のほぼ中央に建つ。桁行３４ｍ，梁間１３ｍ規模の２階建大蔵で，腰を高い煉瓦積，外壁を簓子下見風とし，屋根は南北棟の桟瓦葺，寄棟造で南北の妻面を半切妻状に納める特徴的な外観を呈する。醸造場施設の中核的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002714"},{"id":"00002715","register_sub_id":"101","register_pk":"103705","name":"小柳酒造昭和東蔵","kana":"こやなぎしゅぞうしょうわひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29901349,"lng":130.20260926,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積112㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0030","desc":"昭和西蔵の東に並び建つ。桁行１４ｍ，梁間８ｍ規模，南北棟，桟瓦葺，切妻造の２階建で，内部は西壁を西蔵と共有し，西・南壁に出入口を設ける。外観は，腰を煉瓦積，外壁を押縁間隔の広い下見板張として洋風に見せるなど水路沿いに特色ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002715"},{"id":"00002718","register_sub_id":"101","register_pk":"103708","name":"小柳酒造西貯水槽","kana":"こやなぎしゅぞうにしちょすいそう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29875437,"lng":130.20259251,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"煉瓦造、建築面積4.8㎡","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0033","desc":"煙突の東面及び釜場南面に接して建つ。１．７ｍ×２．８ｍの長方形平面で，高さ４．５ｍ。煉瓦造柱脚の上に水槽を築き，頂部に生子鉄板による南北棟の招き屋根を架ける。水槽部には現在２条の開き止め鉄棒を廻している。醸造施設の近代化を示す遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002718"},{"id":"00002719","register_sub_id":"101","register_pk":"103709","name":"小柳酒造東貯水槽","kana":"こやなぎしゅぞうひがしちょすいそう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29876884,"lng":130.20265816,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"煉瓦造、建築面積4㎡","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0034","desc":"西貯水槽の東方に位置し，釜場南面に接して建つ。２．５ｍ×１．６ｍの長方形平面で，高さ４．４ｍ。６本の煉瓦造柱脚の上部をアーチで繋いで水槽の支持体とし，頂部には釜場南面から生子鉄板の片流れ屋根を架ける。煙突，西貯水槽などと同様に外構の主要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002719"},{"id":"00002721","register_sub_id":"101","register_pk":"103711","name":"小柳酒造ビン詰場","kana":"こやなぎしゅぞうびんづめじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29890444,"lng":130.20265363,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0036","desc":"昭和西蔵の東，昭和東蔵の南，釜場の北に位置する。桁行１０ｍ，梁間９ｍ規模で，南北棟，切妻造，桟瓦葺とし，小屋は二重梁，外部の西面は縦羽目張りとする。簡素なつくりであるが，造り酒屋における最終工程を物語る施設として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002721"},{"id":"00002720","register_sub_id":"101","register_pk":"103710","name":"小柳酒造ポンプ小屋","kana":"こやなぎしゅぞうぽんぷごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29867933,"lng":130.20261344,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"煉瓦造、建築面積5.3㎡","structure_material":"煉瓦造","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0035","desc":"東貯水槽の南方に位置する。平面規模は１．８ｍ×３ｍで，東・南・西の３面に厚１枚の煉瓦造壁を築き，北面は欠円アーチを間口一杯に架けて入口とする。煉瓦は鉱滓煉瓦で，屋根は陸屋根に造る。大正１５年着手の昭和蔵・釜場などの一連の改良施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002720"}];
